//! Commit graph layout: gives each commit a column ("lane") and lists the line
//! segments to draw between one row and the next.

use crate::git::CommitRow;
use git2::Oid;
use std::collections::HashMap;

#[derive(Clone, Debug, Default)]
pub struct Segment {
    /// Column at the upper row.
    pub from: usize,
    /// Column at the lower row.
    pub to: usize,
    pub color: usize,
}

#[derive(Clone, Debug, Default)]
pub struct RowLayout {
    pub col: usize,
    pub color: usize,
    pub is_merge: bool,
    /// Segments from this row's centre to the next row's centre.
    pub down: Vec<Segment>,
}

#[derive(Clone, Debug, Default)]
pub struct Layout {
    pub rows: Vec<RowLayout>,
    pub max_cols: usize,
}

pub fn layout(commits: &[CommitRow]) -> Layout {
    let index: HashMap<Oid, usize> = commits.iter().enumerate().map(|(i, c)| (c.id, i)).collect();
    // Each lane expects one commit id and carries a colour.
    let mut lanes: Vec<Option<(Oid, usize)>> = Vec::new();
    let mut next_color = 0usize;
    let mut rows: Vec<RowLayout> = Vec::with_capacity(commits.len());
    let mut max_cols = 1;

    let alloc = |lanes: &mut Vec<Option<(Oid, usize)>>| -> usize {
        if let Some(i) = lanes.iter().position(|l| l.is_none()) {
            i
        } else {
            lanes.push(None);
            lanes.len() - 1
        }
    };

    for c in commits.iter() {
        // Where does this commit sit?
        let mut col = lanes.iter().position(|l| matches!(l, Some((o, _)) if *o == c.id));
        let color;
        match col {
            Some(i) => color = lanes[i].unwrap().1,
            None => {
                let i = alloc(&mut lanes);
                color = next_color;
                next_color += 1;
                col = Some(i);
            }
        }
        let col = col.unwrap();
        // Other lanes that were waiting for this commit end here.
        for l in lanes.iter_mut() {
            if matches!(l, Some((o, _)) if *o == c.id) {
                *l = None;
            }
        }
        let mut origin_cols: Vec<usize> = Vec::new();
        // First parent continues in the same lane.
        let parents: Vec<Oid> = c.parents.iter().copied().filter(|p| index.contains_key(p)).collect();
        if let Some(p0) = parents.first() {
            if let Some(existing) = lanes.iter().position(|l| matches!(l, Some((o, _)) if o == p0)) {
                // Parent already expected elsewhere: join that lane.
                origin_cols.push(existing);
            } else {
                lanes[col] = Some((*p0, color));
                origin_cols.push(col);
            }
        }
        for p in parents.iter().skip(1) {
            if let Some(existing) = lanes.iter().position(|l| matches!(l, Some((o, _)) if o == p)) {
                origin_cols.push(existing);
            } else {
                let k = alloc(&mut lanes);
                lanes[k] = Some((*p, next_color));
                next_color += 1;
                origin_cols.push(k);
            }
        }
        while matches!(lanes.last(), Some(None)) {
            lanes.pop();
        }
        max_cols = max_cols.max(lanes.len()).max(col + 1);
        // Segments going down from this row.
        let mut down = Vec::new();
        for (k, l) in lanes.iter().enumerate() {
            if let Some((_, colr)) = l {
                let from = if origin_cols.contains(&k) { col } else { k };
                down.push(Segment { from, to: k, color: *colr });
            }
        }
        // A parent that joins a lane already present also needs a line from the node.
        for &k in &origin_cols {
            if !down.iter().any(|s| s.from == col && s.to == k) {
                let colr = lanes.get(k).and_then(|l| l.map(|x| x.1)).unwrap_or(color);
                down.push(Segment { from: col, to: k, color: colr });
            }
        }
        rows.push(RowLayout { col, color, is_merge: c.parents.len() > 1, down });
    }

    // The lower end of a segment lands on the next row's node when that row is
    // the commit the lane was waiting for.
    for r in 0..rows.len().saturating_sub(1) {
        let next_col = rows[r + 1].col;
        let next_id = commits[r + 1].id;
        let mut fixed = Vec::new();
        for s in &rows[r].down {
            fixed.push(s.clone());
        }
        // Lanes whose expected commit is the next row converge into it.
        let expected = expected_after(commits, &rows, r);
        for s in fixed.iter_mut() {
            if expected.get(&s.to) == Some(&next_id) {
                s.to = next_col;
            }
        }
        rows[r].down = fixed;
    }
    if let Some(last) = rows.last_mut() {
        last.down.clear();
    }
    Layout { rows, max_cols }
}

/// Re-derive which commit each lane waits for after row `r` (cheap replay of the
/// parents of rows 0..=r for the lanes that are still open).
fn expected_after(commits: &[CommitRow], rows: &[RowLayout], r: usize) -> HashMap<usize, Oid> {
    let mut map = HashMap::new();
    let c = &commits[r];
    let row = &rows[r];
    // A lane continues to the next row; if the next commit is one of this commit's
    // parents, or the lane's line ends at the next commit, connect it.
    for s in &row.down {
        if s.from == row.col {
            // Lines leaving the node go to one of the parents.
            for p in &c.parents {
                if Some(*p) == commits.get(r + 1).map(|n| n.id) && s.to == rows[r + 1].col {
                    map.insert(s.to, *p);
                }
            }
        }
    }
    // Lanes passing straight through end at the next row when it sits in that lane.
    if let Some(n) = commits.get(r + 1) {
        let ncol = rows[r + 1].col;
        for s in &row.down {
            if s.to == ncol {
                map.insert(s.to, n.id);
            }
        }
        // Converging lanes: those whose lane closes at the next row.
        let open_next: Vec<usize> = rows[r + 1].down.iter().map(|s| s.from).collect();
        for s in &row.down {
            if s.to != ncol && !open_next.contains(&s.to) && !rows[r + 1].down.iter().any(|d| d.to == s.to && d.from == s.to) {
                map.insert(s.to, n.id);
            }
        }
    }
    map
}

/// Colours of the lanes, in order (bright on dark, similar to the reference).
pub const LANE_COLORS: [u32; 10] = [
    0x15A0BF, 0x0669F7, 0x8E00C2, 0xC517B6, 0xD90171, 0xCD0101, 0xF25D2E, 0xF2CA33, 0x7BD938, 0x2ECE9D,
];

