            .call()
            .map_err(http_err)?
            .into_json()
            .map_err(|e| e.to_string())?,
        ApiKind::Ollama => agent.get(&format!("{base}/api/tags")).call().map_err(http_err)?.into_json().map_err(|e| e.to_string())?,
    };
    let mut out: Vec<String> = Vec::new();
    if let Some(a) = v["data"].as_array() {
