                        let first = conn.as_ref().map(|c| c.0.session.is_none()).unwrap_or(true);
                        let text = if first { format!("{}\n\n{}", s.system_prompt, text) } else { text };
                        let res = conn.as_mut().unwrap().0.prompt(&text, &tx_ev);
