                    "ff-only" => PullMode::FastForwardOnly,
                    "rebase" => PullMode::Rebase,
                    "fetch" => PullMode::FetchAll,
                    _ => PullMode::FastForwardIfPossible,
                };
                git::pull(&e, &repo, mode, None)
