            "git_revert" => git::revert(&e, &repo, git::parse_oid(&repo, &str_arg("rev"))?),
            "git_clone" => git::clone(&e, &str_arg("url"), &PathBuf::from(str_arg("dest")), args["shallow"].as_bool().unwrap_or(false), None)
                .map(|p| format!("Cloned into {}", p.display())),
