        let c = center + Vec2::new(dx * s, -s * 0.22 + if dx == 0.0 { -s * 0.12 } else { 0.0 });
        painter.circle_filled(c, s * 0.2, dark);
        painter.circle_filled(c + Vec2::new(-s * 0.07, -s * 0.03), s * 0.045, color);
        painter.circle_filled(c + Vec2::new(s * 0.07, -s * 0.03), s * 0.045, color);
