pub fn pixel_avatar(painter: &egui::Painter, rect: Rect) {
    const MAP: [&str; 6] = ["..X..X..", ".XXXXXX.", "XX.XX.XX", "XXXXXXXX", ".XXXXXX.", ".X.XX.X."];
    let cell = rect.width() / 8.0;
