impl RepoTab {
    pub fn new(path: PathBuf) -> Self {
        let mut closed = HashSet::new();
        for s in ["tags", "submodules", "worktrees"] {
            closed.insert(s.to_string());
        }
        Self {
            path,
            snap: None,
            error: None,
            layout: GraphLayout::default(),
            sel: Sel::None,
            detail: None,
            diff: None,
            filter: String::new(),
            search: String::new(),
            search_open: false,
            left_open: true,
            left_tab: LeftTab::List,
            closed_sections: closed,
            closed_folders: HashSet::new(),
            summary: String::new(),
            description: String::new(),
            amend: false,
            undo: vec![],
            redo: vec![],
            last_poll: 0.0,
            fingerprint: String::new(),
            terminal_open: false,
            term_input: String::new(),
            term_output: String::new(),
            right: RightView::Details,
            ai_msgs: vec![],
            ai_input: String::new(),
            ai_busy: false,
            ai_status: String::new(),
            scroll_to: None,
            last_fetch: 0.0,
            hud: Hud::default(),
        }
    }

    pub fn name(&self) -> String {
        self.snap.as_ref().map(|s| s.name.clone()).unwrap_or_else(|| git::repo_name(&self.path))
    }

    pub fn reload(&mut self, max: usize) {
        match git::load(&self.path, max) {
            Ok(s) => {
                let prev_sel_id = match self.sel {
                    Sel::Commit(i) => self.snap.as_ref().and_then(|o| o.commits.get(i)).map(|c| c.id),
                    _ => None,
                };
                self.layout = graph::layout(&s.commits);
                self.fingerprint = fingerprint(&self.path);
                if let Some(id) = prev_sel_id {
                    self.sel = s.row_of(id).map(Sel::Commit).unwrap_or(Sel::None);
                }
                if self.sel == Sel::Wip && s.wip.is_empty() {
                    self.sel = Sel::None;
                }
                self.snap = Some(s);
                self.error = None;
                self.refresh_detail();
            }
            Err(e) => self.error = Some(e),
        }
    }

    pub fn refresh_detail(&mut self) {
        self.detail = None;
        if let (Sel::Commit(i), Some(s)) = (self.sel, &self.snap) {
            if let Some(c) = s.commits.get(i) {
                self.detail = git::commit_detail(&self.path, c.id).ok();
            }
        }
    }

    pub fn select(&mut self, sel: Sel) {
        if self.sel != sel {
            self.sel = sel;
            self.diff = None;
            self.refresh_detail();
        }
    }

    pub fn has_wip(&self) -> bool {
        self.snap.as_ref().map(|s| !s.wip.is_empty()).unwrap_or(false)
    }

    pub fn row_count(&self) -> usize {
        self.snap.as_ref().map(|s| s.commits.len()).unwrap_or(0) + usize::from(self.has_wip())
    }

    /// Move the selection by `delta` rows (keyboard navigation).
    pub fn move_selection(&mut self, delta: i32) {
        let wip = self.has_wip();
        let n = self.row_count() as i32;
        if n == 0 {
            return;
        }
        let cur: i32 = match self.sel {
            Sel::None => -1,
            Sel::Wip => 0,
            Sel::Commit(i) => i as i32 + i32::from(wip),
        };
        let next = (cur + delta).clamp(0, n - 1);
        let sel = if wip && next == 0 { Sel::Wip } else { Sel::Commit((next - i32::from(wip)) as usize) };
        self.select(sel);
        self.scroll_to = Some(next as usize);
    }

    pub fn selected_oid(&self) -> Option<Oid> {
        match self.sel {
            Sel::Commit(i) => self.snap.as_ref().and_then(|s| s.commits.get(i)).map(|c| c.id),
            _ => None,
        }
    }

    // -----------------------------------------------------------------------
    // Drawing
    // -----------------------------------------------------------------------

    pub fn show(&mut self, ui: &mut Ui, settings: &Settings, recent: &[(String, String)], acts: &mut Vec<RepoAction>, ai_on: bool) {
        self.hud = Hud::default();
        egui::TopBottomPanel::top("repo_toolbar")
            .exact_height(46.0)
            .frame(egui::Frame::none().fill(TOOLBAR))
            .show_inside(ui, |ui| self.toolbar(ui, recent, acts));

        if self.terminal_open {
            egui::TopBottomPanel::bottom("repo_terminal")
                .resizable(true)
                .default_height(200.0)
                .frame(egui::Frame::none().fill(hex(0x16181C)).inner_margin(egui::Margin::same(8.0)))
                .show_inside(ui, |ui| self.terminal(ui, acts));
        }

        if self.left_open {
            egui::SidePanel::left("repo_left")
                .exact_width(settings.left_panel_width.clamp(160.0, 400.0))
                .resizable(false)
                .frame(egui::Frame::none().fill(PANEL))
                .show_inside(ui, |ui| self.left_panel(ui, acts, ai_on));
        } else {
            egui::SidePanel::left("repo_left_closed")
                .exact_width(30.0)
                .resizable(false)
                .frame(egui::Frame::none().fill(PANEL))
                .show_inside(ui, |ui| {
                    let r = ui.max_rect();
                    let c = Pos2::new(r.center().x, r.top() + 16.0);
                    let resp = ui.interact(Rect::from_center_size(c, Vec2::splat(20.0)), ui.id().with("open_left"), Sense::click());
                    ui.painter().circle_filled(c, 9.0, hex(0xC9CCD1));
                    text_at(ui, c, Align2::CENTER_CENTER, ic::CARET_RIGHT, bold(12.0), PANEL);
                    if resp.clicked() {
                        self.left_open = true;
                    }
                });
        }

        let show_right = self.sel != Sel::None || self.right == RightView::Ai;
        if show_right {
            egui::SidePanel::right("repo_right")
                .default_width(380.0)
                .min_width(300.0)
                .max_width(620.0)
                .resizable(true)
                .frame(egui::Frame::none().fill(PANEL))
                .show_inside(ui, |ui| {
                    if self.right == RightView::Ai {
                        self.ai_panel(ui, acts, ai_on);
                    } else if self.sel == Sel::Wip {
                        self.wip_panel(ui, acts, ai_on);
                    } else {
                        self.commit_panel(ui, acts, ai_on);
                    }
                });
        }

        egui::CentralPanel::default().frame(egui::Frame::none().fill(CONTENT)).show_inside(ui, |ui| {
            if let Some(e) = &self.error {
                ui.add_space(40.0);
                ui.vertical_centered(|ui| {
                    ui.label(egui::RichText::new(ic::WARNING).size(36.0).color(MOD_YELLOW));
                    ui.label(egui::RichText::new(t("repo.open_error")).size(18.0));
                    ui.label(egui::RichText::new(e).color(TEXT_DIM));
                });
                return;
            }
            if self.diff.is_some() {
                self.diff_view(ui, acts);
            } else {
                self.graph_view(ui, acts);
            }
        });
    }

    fn toolbar(&mut self, ui: &mut Ui, recent: &[(String, String)], acts: &mut Vec<RepoAction>) {
        self.hud.toolbar = true;
        let rect = ui.max_rect();
        let p = ui.painter().clone();
        let top = rect.top();
        // Repository / branch pickers
        let x0 = rect.left() + 18.0;
        p.text(Pos2::new(x0, top + 9.0), Align2::LEFT_CENTER, t("toolbar.repository"), font(11.5), TEXT_DIM);
        let name = self.name();
        let nr = p.text(Pos2::new(x0, top + 28.0), Align2::LEFT_CENTER, &name, bold(16.5), TEXT_BRIGHT);
        p.text(Pos2::new(nr.right() + 6.0, top + 29.0), Align2::LEFT_CENTER, "▾", font(12.0), TEXT);
        let repo_rect = Rect::from_min_max(Pos2::new(x0 - 4.0, top + 2.0), Pos2::new(nr.right() + 18.0, top + 44.0));
        let repo_resp = ui.interact(repo_rect, ui.id().with("repo_pick"), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
        let chev_x = nr.right() + 30.0;
        p.text(Pos2::new(chev_x, top + 28.0), Align2::LEFT_CENTER, ic::CARET_RIGHT, font(16.0), TEXT_DIM);
        let bx = chev_x + 25.0;
        p.text(Pos2::new(bx, top + 9.0), Align2::LEFT_CENTER, t("toolbar.branch"), font(11.5), TEXT_DIM);
        let branch = self.snap.as_ref().map(|s| s.head_name.clone()).unwrap_or_default();
        let br = p.text(Pos2::new(bx, top + 28.0), Align2::LEFT_CENTER, &branch, font(15.5), TEXT_BRIGHT);
        let caret_x = (br.right() + 30.0).max(bx + 78.0);
        p.text(Pos2::new(caret_x, top + 29.0), Align2::LEFT_CENTER, "▾", font(12.0), TEXT);
        let branch_rect = Rect::from_min_max(Pos2::new(bx - 4.0, top + 2.0), Pos2::new(caret_x + 14.0, top + 44.0));
        let branch_resp = ui.interact(branch_rect, ui.id().with("branch_pick"), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);

        egui::popup::popup_below_widget(ui, ui.id().with("repo_pop"), &repo_resp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
            ui.set_min_width(260.0);
            for (n, path) in recent {
                if ui.button(format!("{}  {}", ic::GIT_BRANCH, n)).on_hover_text(path).clicked() {
                    acts.push(RepoAction::SwitchRepo(path.clone()));
                }
            }
            ui.separator();
            if ui.button(format!("{}  {}", ic::FOLDER_OPEN, t("menu.open_repo"))).clicked() {
                acts.push(RepoAction::OpenRepo);
            }
        });
        if repo_resp.clicked() {
            ui.memory_mut(|m| m.toggle_popup(ui.id().with("repo_pop")));
        }
        egui::popup::popup_below_widget(ui, ui.id().with("branch_pop"), &branch_resp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
            ui.set_min_width(240.0);
            if let Some(s) = &self.snap {
                for b in &s.local {
                    let label = if b.is_head { format!("{}  {}", ic::CHECK, b.name) } else { format!("     {}", b.name) };
                    if ui.button(label).clicked() && !b.is_head {
                        acts.push(RepoAction::Checkout(b.name.clone()));
                    }
                }
            }
            ui.separator();
            if ui.button(format!("{}  {}", ic::PLUS, t("toolbar.new_branch"))).clicked() {
                acts.push(RepoAction::NewBranch(None));
            }
        });
        if branch_resp.clicked() {
            ui.memory_mut(|m| m.toggle_popup(ui.id().with("branch_pop")));
        }

        // Action buttons
        let has_wip = self.has_wip();
        let has_stash = self.snap.as_ref().map(|s| !s.stashes.is_empty()).unwrap_or(false);
        let start = (caret_x + 120.0).max(rect.left() + 385.0);
        let bw = 52.0;
        let mut x = start;
        let mut btn = |ui: &mut Ui, x: f32, label: &str, icon: &str, enabled: bool, id: &str| -> egui::Response {
            let r = Rect::from_min_size(Pos2::new(x - bw / 2.0, top + 1.0), Vec2::new(bw, 44.0));
            let resp = ui.interact(r, ui.id().with(id), if enabled { Sense::click() } else { Sense::hover() });
            if enabled && resp.hovered() {
                ui.painter().rect_filled(r.shrink(1.0), Rounding::same(3.0), hex(0x3D424C));
            }
            let (lc, icc) = if enabled { (hex(0xB9BDC4), TEXT_BRIGHT) } else { (TEXT_FAINT, TEXT_FAINT) };
            ui.painter().text(Pos2::new(x, top + 9.0), Align2::CENTER_CENTER, label, font(11.5), lc);
            ui.painter().text(Pos2::new(x, top + 30.0), Align2::CENTER_CENTER, icon, font(20.0), icc);
            if enabled {
                resp.on_hover_cursor(CursorIcon::PointingHand)
            } else {
                resp
            }
        };
        if btn(ui, x, &t("toolbar.undo"), ic::ARROW_COUNTER_CLOCKWISE, !self.undo.is_empty(), "undo").clicked() {
            acts.push(RepoAction::Undo);
        }
        x += bw;
        if btn(ui, x, &t("toolbar.redo"), ic::ARROW_CLOCKWISE, !self.redo.is_empty(), "redo").clicked() {
            acts.push(RepoAction::Redo);
        }
        x += bw;
        let pull = btn(ui, x, &t("toolbar.pull"), ic::ARROW_LINE_DOWN, true, "pull");
        if pull.clicked() {
            acts.push(RepoAction::Pull(PullMode::FastForwardIfPossible));
        }
        // dropdown caret for pull options
        let caret = Rect::from_center_size(Pos2::new(x + 32.0, top + 18.0), Vec2::new(14.0, 26.0));
        let caret_resp = ui.interact(caret, ui.id().with("pull_caret"), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
        ui.painter().text(caret.center(), Align2::CENTER_CENTER, "▾", font(12.0), TEXT);
        egui::popup::popup_below_widget(ui, ui.id().with("pull_pop"), &caret_resp, egui::PopupCloseBehavior::CloseOnClick, |ui| {
            ui.set_min_width(230.0);
            for (m, k) in [
                (PullMode::FetchAll, "pull.fetch_all"),
                (PullMode::FastForwardIfPossible, "pull.ff_if_possible"),
                (PullMode::FastForwardOnly, "pull.ff_only"),
                (PullMode::Rebase, "pull.rebase"),
            ] {
                if ui.button(t(k)).clicked() {
                    acts.push(RepoAction::Pull(m));
                }
            }
        });
        if caret_resp.clicked() {
            ui.memory_mut(|m| m.toggle_popup(ui.id().with("pull_pop")));
        }
        x += bw + 15.0;
        let push = btn(ui, x, &t("toolbar.push"), ic::ARROW_LINE_UP, true, "push");
        if push.clicked() {
            acts.push(RepoAction::Push(false));
        }
        push.context_menu(|ui| {
            if ui.button(t("push.force")).clicked() {
                acts.push(RepoAction::Push(true));
                ui.close_menu();
            }
        });
        x += bw;
        if btn(ui, x, &t("toolbar.branch"), ic::GIT_BRANCH, self.snap.as_ref().map(|s| !s.unborn).unwrap_or(false), "branchbtn").clicked() {
            acts.push(RepoAction::NewBranch(self.selected_oid()));
        }
        x += bw;
        if btn(ui, x, &t("toolbar.stash"), ic::TRAY_ARROW_DOWN, has_wip, "stash").clicked() {
            acts.push(RepoAction::Stash);
        }
        x += bw;
        if btn(ui, x, &t("toolbar.pop"), ic::TRAY_ARROW_UP, has_stash, "pop").clicked() {
            acts.push(RepoAction::Pop(0));
        }
        x += bw / 2.0 + 4.0;
        p.line_segment([Pos2::new(x, top + 4.0), Pos2::new(x, top + 44.0)], Stroke::new(1.0, hex(0x4A4F59)));
        x += 31.0;
        let term = btn(ui, x, &t("toolbar.terminal"), ic::TERMINAL_WINDOW, true, "term");
        if term.clicked() {
            self.terminal_open = !self.terminal_open;
        }
        term.context_menu(|ui| {
            if ui.button(t("toolbar.open_external_terminal")).clicked() {
                acts.push(RepoAction::OpenTerminal);
                ui.close_menu();
            }
        });
        x += bw + 6.0;
        if btn(ui, x, &t("toolbar.ai"), ic::SPARKLE, true, "aibtn").clicked() {
            self.right = if self.right == RightView::Ai { RightView::Details } else { RightView::Ai };
        }

        // Right side: Actions, Search
        let rx = rect.right() - 24.0;
        let search = btn(ui, rx, &t("toolbar.search"), ic::MAGNIFYING_GLASS, true, "search");
        if search.clicked() {
            self.search_open = !self.search_open;
            if !self.search_open {
                self.search.clear();
            }
        }
        let actions = btn(ui, rx - 52.0, &t("toolbar.actions"), ic::SLIDERS, true, "actions");
        egui::popup::popup_below_widget(ui, ui.id().with("actions_pop"), &actions, egui::PopupCloseBehavior::CloseOnClick, |ui| {
            ui.set_min_width(250.0);
            let items: [(&str, &str, RepoAction); 8] = [
                (ic::ARROWS_CLOCKWISE, "actions.refresh", RepoAction::Refresh),
                (ic::CLOUD_ARROW_DOWN, "actions.fetch_all", RepoAction::Fetch),
                (ic::FOLDER_OPEN, "actions.open_folder", RepoAction::OpenFolder),
                (ic::CODE_BLOCK, "actions.open_editor", RepoAction::OpenEditor),
                (ic::TERMINAL_WINDOW, "toolbar.open_external_terminal", RepoAction::OpenTerminal),
                (ic::LINK, "actions.add_remote", RepoAction::AddRemote),
                (ic::SPARKLE, "actions.ai_review", RepoAction::AiReview),
                (ic::COPY, "actions.copy_path", RepoAction::Copy(self.path.display().to_string())),
            ];
            for (icon, key, a) in items {
                if ui.button(format!("{icon}  {}", t(key))).clicked() {
                    acts.push(a);
                }
            }
        });
        if actions.clicked() {
            ui.memory_mut(|m| m.toggle_popup(ui.id().with("actions_pop")));
        }
    }

    fn left_panel(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>, ai_on: bool) {
        self.hud.left_panel = true;
        let rect = ui.max_rect();
        let p = ui.painter().clone();
        p.line_segment([rect.right_top(), rect.right_bottom()], Stroke::new(1.0, CONTENT));
        // collapse button + List / Agents switch
        let c = Pos2::new(rect.left() + 18.0, rect.top() + 18.0);
        let col_resp = ui.interact(Rect::from_center_size(c, Vec2::splat(20.0)), ui.id().with("collapse"), Sense::click());
        p.circle_filled(c, 9.0, hex(0xC9CCD1));
        p.text(c, Align2::CENTER_CENTER, ic::CARET_LEFT, bold(12.0), PANEL);
        if col_resp.clicked() {
            self.left_open = false;
        }
        let seg = Rect::from_min_max(Pos2::new(rect.left() + 36.0, rect.top() + 7.0), Pos2::new(rect.right() - 9.0, rect.top() + 30.0));
        p.rect(seg, Rounding::same(3.0), PANEL, Stroke::new(1.0, hex(0x4A4F59)));
        let half = seg.width() * 0.5;
        let lr = Rect::from_min_size(seg.min, Vec2::new(half, seg.height()));
        let ar = Rect::from_min_size(Pos2::new(seg.left() + half, seg.top()), Vec2::new(half, seg.height()));
        for (r, tab, icon, key) in [(lr, LeftTab::List, ic::LIST_BULLETS, "left.list"), (ar, LeftTab::Agents, ic::ROBOT, "left.agents")] {
            let resp = ui.interact(r, ui.id().with(key), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
            if self.left_tab == tab {
                p.rect(r.shrink(1.0), Rounding::same(2.0), SELECT, Stroke::new(1.0, hex(0x5A7BB5)));
            }
            let label = format!("{icon} {}", t(key));
            p.text(r.center(), Align2::CENTER_CENTER, label, font(13.0), TEXT_BRIGHT);
            if resp.clicked() {
                self.left_tab = tab;
                if tab == LeftTab::Agents {
                    self.right = RightView::Ai;
                }
            }
        }
        ui.add_space(38.0);
        if self.left_tab == LeftTab::Agents {
            self.agents_tab(ui, acts, ai_on);
            return;
        }
        let Some(s) = self.snap.clone() else { return };
        // Viewing N + filter
        ui.horizontal(|ui| {
            ui.add_space(12.0);
            ui.label(egui::RichText::new(t("left.viewing")).size(13.5).color(TEXT));
            ui.label(egui::RichText::new(s.commits.len().to_string()).size(13.5).color(LINK_SOFT));
        });
        ui.add_space(2.0);
        ui.horizontal(|ui| {
            ui.add_space(9.0);
            let w = ui.available_width() - 10.0;
            let r = input(ui, &mut self.filter, &t("left.filter"), w, 22.0, INPUT);
            let icon_pos = Pos2::new(r.rect.right() + 2.0, r.rect.center().y);
            let _ = icon_pos;
        });
        let fr = ui.min_rect();
        p.text(Pos2::new(rect.right() - 20.0, fr.bottom() - 11.0), Align2::CENTER_CENTER, ic::MAGNIFYING_GLASS, font(14.0), TEXT_DIM);
        ui.add_space(6.0);
        let filter = self.filter.to_lowercase();
        let matches = |n: &str| filter.is_empty() || n.to_lowercase().contains(&filter);

        ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
            ui.spacing_mut().item_spacing.y = 0.0;
            // LOCAL
            let local: Vec<_> = s.local.iter().filter(|b| matches(&b.name)).collect();
            if self.section(ui, "local", ic::LAPTOP, &t("left.local"), local.len()) {
                for b in local {
                    let resp = self.item_row(ui, 1, if b.is_head { ic::CHECK } else { ic::GIT_BRANCH }, &b.name, b.is_head, b.ahead, b.behind);
                    if resp.double_clicked() && !b.is_head {
                        acts.push(RepoAction::Checkout(b.name.clone()));
                    }
                    if resp.clicked() {
                        if let Some(o) = b.oid {
                            if let Some(i) = s.row_of(o) {
                                self.select(Sel::Commit(i));
                                self.scroll_to = Some(i + usize::from(!s.wip.is_empty()));
                            }
                        }
                    }
                    let name = b.name.clone();
                    let head = b.is_head;
                    let oid = b.oid;
                    resp.context_menu(|ui| {
                        if !head && ui.button(tf("ctx.checkout", &[&name])).clicked() {
                            acts.push(RepoAction::Checkout(name.clone()));
                            ui.close_menu();
                        }
                        if !head && ui.button(tf("ctx.merge_into_current", &[&name])).clicked() {
                            acts.push(RepoAction::Merge(name.clone()));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.create_branch_here")).clicked() {
                            acts.push(RepoAction::NewBranch(oid));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.rename_branch")).clicked() {
                            acts.push(RepoAction::RenameBranch(name.clone()));
                            ui.close_menu();
                        }
                        if !head && ui.button(tf("ctx.delete_branch", &[&name])).clicked() {
                            acts.push(RepoAction::DeleteBranch(name.clone()));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.copy_name")).clicked() {
                            acts.push(RepoAction::Copy(name.clone()));
                            ui.close_menu();
                        }
                    });
                }
            }
            // REMOTE
            let total_remote: usize = s.remotes.iter().map(|r| r.branches.len()).sum();
            if self.section(ui, "remote", ic::CLOUD, &t("left.remote"), total_remote) {
                for r in &s.remotes {
                    let resp = self.item_row(ui, 1, ic::GLOBE, &r.name, false, 0, 0).on_hover_text(&r.url);
                    let rn = r.name.clone();
                    resp.context_menu(|ui| {
                        if ui.button(tf("ctx.fetch_remote", &[&rn])).clicked() {
                            acts.push(RepoAction::Fetch);
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.remove_remote")).clicked() {
                            acts.push(RepoAction::RemoveRemote(rn.clone()));
                            ui.close_menu();
                        }
                    });
                    let mut last_folder: Option<String> = None;
                    for b in r.branches.iter().filter(|b| matches(&b.name)) {
                        let (folder, leaf) = match b.name.split_once('/') {
                            Some((f, l)) => (Some(f.to_string()), l.to_string()),
                            None => (None, b.name.clone()),
                        };
                        let mut depth = 2;
                        if let Some(f) = &folder {
                            let key = format!("{}/{}", r.name, f);
                            if last_folder.as_ref() != Some(f) {
                                let open = !self.closed_folders.contains(&key);
                                let fr = self.item_row(ui, 2, if open { ic::FOLDER_OPEN } else { ic::FOLDER_SIMPLE }, f, false, 0, 0);
                                if fr.clicked() {
                                    if open {
                                        self.closed_folders.insert(key.clone());
                                    } else {
                                        self.closed_folders.remove(&key);
                                    }
                                }
                                last_folder = Some(f.clone());
                            }
                            if self.closed_folders.contains(&key) {
                                continue;
                            }
                            depth = 3;
                        }
                        let full = format!("{}/{}", r.name, b.name);
                        let resp = self.item_row(ui, depth, ic::GIT_BRANCH, &leaf, false, 0, 0).on_hover_text(&full);
                        if resp.double_clicked() {
                            acts.push(RepoAction::Checkout(full.clone()));
                        }
                        if resp.clicked() {
                            if let Some(i) = b.oid.and_then(|o| s.row_of(o)) {
                                self.select(Sel::Commit(i));
                                self.scroll_to = Some(i + usize::from(!s.wip.is_empty()));
                            }
                        }
                        resp.context_menu(|ui| {
                            if ui.button(tf("ctx.checkout", &[&full])).clicked() {
                                acts.push(RepoAction::Checkout(full.clone()));
                                ui.close_menu();
                            }
                            if ui.button(tf("ctx.merge_into_current", &[&full])).clicked() {
                                acts.push(RepoAction::Merge(full.clone()));
                                ui.close_menu();
                            }
                        });
                    }
                }
            }
            // STASHES
            if self.section(ui, "stashes", ic::ARCHIVE, &t("left.stashes"), s.stashes.len()) {
                for st in &s.stashes {
                    let resp = self.item_row(ui, 1, ic::TRAY, &st.message, false, 0, 0);
                    let i = st.index;
                    resp.context_menu(|ui| {
                        if ui.button(t("ctx.apply_stash")).clicked() {
                            acts.push(RepoAction::ApplyStash(i));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.pop_stash")).clicked() {
                            acts.push(RepoAction::Pop(i));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.drop_stash")).clicked() {
                            acts.push(RepoAction::DropStash(i));
                            ui.close_menu();
                        }
                    });
                }
            }
            // TAGS
            let tags: Vec<_> = s.tags.iter().filter(|(n, _)| matches(n)).collect();
            if self.section(ui, "tags", ic::TAG, &t("left.tags"), tags.len()) {
                for (n, o) in tags {
                    let resp = self.item_row(ui, 1, ic::TAG, n, false, 0, 0);
                    if resp.clicked() {
                        if let Some(i) = s.row_of(*o) {
                            self.select(Sel::Commit(i));
                            self.scroll_to = Some(i + usize::from(!s.wip.is_empty()));
                        }
                    }
                    let nn = n.clone();
                    resp.context_menu(|ui| {
                        if ui.button(t("ctx.delete_tag")).clicked() {
                            acts.push(RepoAction::DeleteTag(nn.clone()));
                            ui.close_menu();
                        }
                    });
                }
            }
            if self.section(ui, "submodules", ic::CUBE, &t("left.submodules"), s.submodules.len()) {
                for (n, _) in &s.submodules {
                    self.item_row(ui, 1, ic::CUBE, n, false, 0, 0);
                }
            }
            if self.section(ui, "worktrees", ic::TREE_STRUCTURE, &t("left.worktrees"), s.worktrees.len()) {
                for n in &s.worktrees {
                    self.item_row(ui, 1, ic::TREE_STRUCTURE, n, false, 0, 0);
                }
            }
        });
    }

    fn section(&mut self, ui: &mut Ui, key: &str, icon: &str, title: &str, count: usize) -> bool {
        let w = ui.available_width();
        let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 30.0), Sense::click());
        let open = !self.closed_sections.contains(key);
        let p = ui.painter();
        p.line_segment([r.left_top(), r.right_top()], Stroke::new(1.0, SECTION_LINE));
        if resp.hovered() {
            p.rect_filled(r.shrink(1.0), Rounding::ZERO, hex(0x2D3038));
        }
        p.text(Pos2::new(r.left() + 12.0, r.center().y), Align2::CENTER_CENTER, if open { ic::CARET_DOWN } else { ic::CARET_RIGHT }, font(13.0), TEXT);
        p.text(Pos2::new(r.left() + 31.0, r.center().y), Align2::CENTER_CENTER, icon, font(14.0), TEXT_DIM);
        p.text(Pos2::new(r.left() + 43.0, r.center().y), Align2::LEFT_CENTER, title, bold(12.5), hex(0xC8CCD2));
        p.text(Pos2::new(r.right() - 12.0, r.center().y), Align2::RIGHT_CENTER, count.to_string(), bold(12.5), hex(0x8EA6D8));
        if resp.clicked() {
            if open {
                self.closed_sections.remove(key);
                self.closed_sections.insert(key.to_string());
            } else {
                self.closed_sections.remove(key);
            }
        }
        if open {
            ui.add_space(2.0);
        }
        open
    }

    #[allow(clippy::too_many_arguments)]
    fn item_row(&self, ui: &mut Ui, depth: usize, icon: &str, label: &str, head: bool, ahead: usize, behind: usize) -> egui::Response {
        let w = ui.available_width();
        let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 24.0), Sense::click());
        let p = ui.painter();
        if head {
            p.rect_filled(r, Rounding::ZERO, HEAD_GREEN);
            let cb = Rect::from_center_size(Pos2::new(r.left() + 11.0, r.center().y), Vec2::splat(13.0));
            p.rect_filled(cb, Rounding::same(2.0), CHECK_GREEN);
            p.text(cb.center(), Align2::CENTER_CENTER, ic::CHECK, bold(10.0), Color32::WHITE);
        } else if resp.hovered() {
            p.rect_filled(r, Rounding::ZERO, hex(0x323641));
        }
        let x = r.left() + 10.0 + depth as f32 * 14.0;
        let icon = if head { ic::GIT_BRANCH } else { icon };
        p.text(Pos2::new(x, r.center().y), Align2::CENTER_CENTER, icon, font(13.0), if head { TEXT } else { TEXT_DIM });
        let mut right = r.right() - 8.0;
        if behind > 0 {
            let rr = p.text(Pos2::new(right, r.center().y), Align2::RIGHT_CENTER, format!("{}{behind}", ic::ARROW_DOWN), font(11.5), TEXT_DIM);
            right = rr.left() - 4.0;
        }
        if ahead > 0 {
            let rr = p.text(Pos2::new(right, r.center().y), Align2::RIGHT_CENTER, format!("{}{ahead}", ic::ARROW_UP), font(11.5), TEXT_DIM);
            right = rr.left() - 4.0;
        }
        let f = if head { bold(13.5) } else { font(13.5) };
        let max = right - (x + 12.0) - 4.0;
        let text = elide(ui, label, &f, max);
        p.text(Pos2::new(x + 12.0, r.center().y), Align2::LEFT_CENTER, text, f, if head { TEXT_BRIGHT } else { TEXT });
        resp.on_hover_cursor(CursorIcon::PointingHand)
    }

    fn agents_tab(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>, ai_on: bool) {
        ui.add_space(4.0);
        egui::Frame::none().inner_margin(egui::Margin::symmetric(12.0, 4.0)).show(ui, |ui| {
            ui.label(egui::RichText::new(t("agents.title")).size(15.0).color(TEXT_BRIGHT));
            ui.add_space(4.0);
            let (c, k) = if ai_on { (CHECK_GREEN, "agents.ready") } else { (MOD_YELLOW, "agents.off") };
            ui.label(egui::RichText::new(format!("● {}", t(k))).color(c).size(12.5));
            ui.add_space(8.0);
            let w = ui.available_width();
            let mut b = |ui: &mut Ui, icon: &str, key: &str| ui.add_sized([w, 28.0], egui::Button::new(format!("{icon}  {}", t(key))));
            if b(ui, ic::CHAT_CIRCLE_TEXT, "agents.open_chat").clicked() {
                self.right = RightView::Ai;
            }
            if let Some(o) = self.selected_oid() {
                if b(ui, ic::SPARKLE, "agents.explain_selected").clicked() {
                    acts.push(RepoAction::AiExplain(o));
                }
            }
            if b(ui, ic::SHIELD_CHECK, "agents.review_wip").clicked() {
                acts.push(RepoAction::AiReview);
            }
            if b(ui, ic::PENCIL_SIMPLE, "agents.commit_message").clicked() {
                acts.push(RepoAction::AiCommitMessage);
            }
            ui.add_space(8.0);
            if b(ui, ic::GEAR, "agents.configure").clicked() {
                acts.push(RepoAction::ConfigureAi);
            }
            ui.add_space(10.0);
            ui.label(egui::RichText::new(t("agents.hint")).size(12.0).color(TEXT_DIM));
        });
    }

    fn graph_view(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>) {
        let Some(s) = self.snap.clone() else {
            ui.centered_and_justified(|ui| ui.spinner());
            return;
        };
        let full = ui.max_rect();
        let wip = !s.wip.is_empty();
        let branch_w = 140.0;
        let lanes = self.layout.max_cols.max(1) as f32;
        let graph_w = (36.0 + (lanes - 1.0) * LANE_W + 48.0).clamp(84.0, 300.0);
        let x_branch = full.left();
        let x_graph = x_branch + branch_w;
        let x_msg = x_graph + graph_w;

        // header
        self.hud.graph_header = true;
        let hdr = Rect::from_min_size(full.min, Vec2::new(full.width(), 22.0));
        let p = ui.painter().clone();
        p.rect_filled(hdr, Rounding::ZERO, PANEL);
        p.text(Pos2::new(x_branch + 16.0, hdr.center().y), Align2::LEFT_CENTER, t("graph.branch_tag"), mono(10.5), TEXT_DIM);
        p.text(Pos2::new(x_graph + 6.0, hdr.center().y), Align2::LEFT_CENTER, t("graph.graph"), mono(10.5), TEXT_DIM);
        p.text(Pos2::new(x_msg + 6.0, hdr.center().y), Align2::LEFT_CENTER, t("graph.message"), mono(10.5), TEXT_DIM);
        for x in [x_graph, x_msg] {
            p.line_segment([Pos2::new(x, hdr.top()), Pos2::new(x, hdr.bottom())], Stroke::new(1.0, CONTENT));
        }
        p.text(Pos2::new(hdr.right() - 10.0, hdr.center().y), Align2::CENTER_CENTER, ic::GEAR, font(12.0), TEXT_DIM);
        let mut y_top = hdr.bottom() + 2.0;

        if self.search_open {
            let r = Rect::from_min_size(Pos2::new(x_msg, y_top + 2.0), Vec2::new((full.right() - x_msg - 12.0).min(420.0), 26.0));
            let mut child = ui.child_ui(r, Layout::left_to_right(Align::Center), None);
            let resp = input(&mut child, &mut self.search, &t("graph.search_hint"), r.width(), 26.0, INPUT);
            if resp.changed() {
                let q = self.search.to_lowercase();
                if let Some(i) = s.commits.iter().position(|c| {
                    !q.is_empty() && (c.summary.to_lowercase().contains(&q) || c.author.to_lowercase().contains(&q) || c.id.to_string().starts_with(&q))
                }) {
                    self.select(Sel::Commit(i));
                    self.scroll_to = Some(i + usize::from(wip));
                }
            }
            if resp.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Escape)) {
                self.search_open = false;
            }
            y_top += 32.0;
        }

        let rows_rect = Rect::from_min_max(Pos2::new(full.left(), y_top), full.max);
        let mut child = ui.child_ui(rows_rect, Layout::top_down(Align::Min), None);
        let n = s.commits.len() + usize::from(wip);
        if n == 0 {
            child.add_space(30.0);
            child.vertical_centered(|ui| {
                ui.label(egui::RichText::new(t("graph.empty")).color(TEXT_DIM).size(15.0));
            });
            return;
        }
        let mut area = ScrollArea::both().auto_shrink([false, false]).id_source("graph_scroll");
        if let Some(target) = self.scroll_to.take() {
            let visible = rows_rect.height();
            let y = target as f32 * ROW_H;
            area = area.vertical_scroll_offset((y - visible / 2.0).max(0.0));
        }
        let search = self.search.to_lowercase();
        area.show_rows(&mut child, ROW_H, n, |ui, range| {
            ui.set_min_width(rows_rect.width());
            let origin = ui.min_rect().min;
            let left = rows_rect.left();
            let width = rows_rect.width().max(ui.available_width());
            let painter = ui.painter().clone();
            let lane_x = |k: usize| x_graph - full.left() + left + 36.0 + k as f32 * LANE_W;
            let head_row = s.head_oid.and_then(|h| s.row_of(h));
            for vi in range.clone() {
                let y0 = origin.y + (vi - range.start) as f32 * ROW_H;
                let row_rect = Rect::from_min_size(Pos2::new(left, y0), Vec2::new(width, ROW_H));
                let cy = row_rect.center().y;
                let resp = ui.interact(row_rect, ui.id().with(("row", vi)), Sense::click());
                self.hud.rows_drawn += 1;
                let is_sel = match self.sel {
                    Sel::Wip => wip && vi == 0,
                    Sel::Commit(i) => vi == i + usize::from(wip),
                    Sel::None => false,
                };
                if is_sel {
                    painter.rect_filled(row_rect, Rounding::ZERO, SELECT_ROW);
                } else if resp.hovered() {
                    painter.rect_filled(row_rect, Rounding::ZERO, hex(0x22252B));
                }
                if wip && vi == 0 {
                    // Work in progress row
                    let col = head_row.map(|r| self.layout.rows[r].col).unwrap_or(0);
                    let color = head_row.map(|r| lane_color(self.layout.rows[r].color)).unwrap_or(lane_color(0));
                    let nx = lane_x(col);
                    let tint = Rect::from_min_max(Pos2::new(nx, cy - 10.0), Pos2::new(x_msg - full.left() + left - 3.0, cy + 10.0));
                    painter.rect_filled(tint, Rounding::ZERO, mix(CONTENT, color, 0.12));
                    dashed_circle(&painter, Pos2::new(nx, cy), NODE_R - 1.0, color);
                    // dotted line down to HEAD
                    let target_y = head_row.map(|r| origin.y + (r + 1) as f32 * ROW_H - (range.start as f32) * ROW_H + ROW_H / 2.0);
                    let end_y = target_y.unwrap_or(cy + ROW_H).min(row_rect.bottom() + ROW_H * 40.0);
                    let mut yy = cy + NODE_R;
                    while yy < end_y - NODE_R {
                        painter.line_segment([Pos2::new(nx, yy), Pos2::new(nx, (yy + 3.0).min(end_y - NODE_R))], Stroke::new(2.0, color));
                        yy += 6.0;
                    }
                    let mx = x_msg - full.left() + left;
                    painter.rect_filled(Rect::from_min_size(Pos2::new(mx - 3.0, cy - 10.0), Vec2::new(2.0, 20.0)), Rounding::ZERO, color);
                    let tr = painter.text(Pos2::new(mx + 6.0, cy), Align2::LEFT_CENTER, "// WIP", font(14.0), TEXT_DIM);
                    let mut x = tr.right() + 12.0;
                    let unst = &s.wip;
                    let modified = unst.unstaged.iter().chain(unst.staged.iter()).filter(|f| f.status == 'M').count();
                    let added = unst.unstaged.iter().chain(unst.staged.iter()).filter(|f| f.status == 'A').count();
                    let deleted = unst.unstaged.iter().chain(unst.staged.iter()).filter(|f| f.status == 'D').count();
                    for (icon, nn, c) in [(ic::PENCIL_SIMPLE, modified, MOD_YELLOW), (ic::PLUS, added, ADD_GREEN), (ic::MINUS, deleted, DEL_RED)] {
                        if nn > 0 {
                            let r = painter.text(Pos2::new(x, cy), Align2::LEFT_CENTER, format!("{icon} {nn}"), font(12.5), c);
                            x = r.right() + 10.0;
                        }
                    }
                    if resp.clicked() {
                        self.select(Sel::Wip);
                        self.right = RightView::Details;
                    }
                    continue;
                }
                let ci = vi - usize::from(wip);
                let c = &s.commits[ci];
                let rl = &self.layout.rows[ci];
                let color = lane_color(rl.color);
                let nx = lane_x(rl.col);
                // segments down to the next row
                for seg in &rl.down {
                    let a = Pos2::new(lane_x(seg.from), cy);
                    let b = Pos2::new(lane_x(seg.to), cy + ROW_H);
                    let st = Stroke::new(2.0, lane_color(seg.color));
                    if (a.x - b.x).abs() < 0.5 {
                        painter.line_segment([a, b], st);
                    } else {
                        let bez = egui::epaint::CubicBezierShape::from_points_stroke(
                            [a, Pos2::new(a.x, cy + ROW_H * 0.55), Pos2::new(b.x, cy + ROW_H * 0.45), b],
                            false,
                            Color32::TRANSPARENT,
                            st,
                        );
                        painter.add(bez);
                    }
                }
                // tint from node to message column + accent bar
                let mx = x_msg - full.left() + left;
                let tint = Rect::from_min_max(Pos2::new(nx, cy - 10.0), Pos2::new(mx - 3.0, cy + 10.0));
                painter.rect_filled(tint, Rounding::ZERO, mix(CONTENT, color, 0.14));
                painter.rect_filled(Rect::from_min_size(Pos2::new(mx - 3.0, cy - 10.0), Vec2::new(2.0, 20.0)), Rounding::ZERO, color);
                // node
                if rl.is_merge {
                    painter.circle_filled(Pos2::new(nx, cy), 6.0, color);
                } else {
                    painter.circle_filled(Pos2::new(nx, cy), NODE_R, color);
                    avatar(&painter, Pos2::new(nx, cy), NODE_R - 2.0, &c.author);
                }
                // refs
                if let Some(refs) = s.refs.get(&c.id) {
                    let mut refs = refs.clone();
                    refs.sort_by_key(|r| (!r.is_head, r.kind != RefKind::Local, r.kind == RefKind::Tag));
                    let first = &refs[0];
                    let bx = left + 10.0;
                    let pill = Rect::from_min_size(Pos2::new(bx, cy - 11.0), Vec2::new(branch_w - 46.0, 22.0));
                    let pill_col = if first.kind == RefKind::Tag { hex(0x4A4F59) } else { mix(CONTENT, color, 0.45) };
                    painter.line_segment([Pos2::new(pill.right(), cy), Pos2::new(nx - NODE_R, cy)], Stroke::new(2.0, mix(CONTENT, color, 0.8)));
                    painter.rect(pill, Rounding::same(2.0), pill_col, Stroke::new(1.0, mix(pill_col, color, 0.5)));
                    let mut tx = pill.left() + 6.0;
                    if first.is_head {
                        let r = painter.text(Pos2::new(tx, cy), Align2::LEFT_CENTER, ic::CHECK, bold(12.0), TEXT_BRIGHT);
                        tx = r.right() + 4.0;
                    }
                    let icon = match first.kind {
                        RefKind::Local => ic::LAPTOP,
                        RefKind::Remote => ic::CLOUD,
                        RefKind::Tag => ic::TAG,
                    };
                    let both = first.kind == RefKind::Local
                        && refs.iter().any(|r| r.kind == RefKind::Remote && r.name.ends_with(&format!("/{}", first.name)));
                    let icons = if both { format!("{icon}{}", ic::CLOUD) } else { icon.to_string() };
                    let iw = text_width(ui, &icons, font(12.0)) + 6.0;
                    let extra = if refs.len() > 1 + usize::from(both) { format!(" +{}", refs.len() - 1 - usize::from(both)) } else { String::new() };
                    let ew = text_width(ui, &extra, font(11.0));
                    let name = elide(ui, &first.name, &bold(12.5), pill.right() - tx - iw - ew - 6.0);
                    let r = painter.text(Pos2::new(tx, cy), Align2::LEFT_CENTER, &name, bold(12.5), TEXT_BRIGHT);
                    let r2 = painter.text(Pos2::new(r.right() + 5.0, cy), Align2::LEFT_CENTER, icons, font(12.0), TEXT);
                    if !extra.is_empty() {
                        painter.text(Pos2::new(r2.right() + 2.0, cy), Align2::LEFT_CENTER, extra, font(11.0), TEXT_DIM);
                    }
                    let all: Vec<String> = refs.iter().map(|r| r.name.clone()).collect();
                    ui.interact(pill, ui.id().with(("pill", vi)), Sense::hover()).on_hover_text(all.join("\n"));
                }
                // message
                let max_w = width - (mx - left) - 110.0;
                let dim = !search.is_empty() && !(c.summary.to_lowercase().contains(&search) || c.author.to_lowercase().contains(&search));
                let sc = if dim { TEXT_FAINT } else { TEXT_BRIGHT };
                let summary = elide(ui, &c.summary, &font(14.0), max_w.max(40.0));
                let r = painter.text(Pos2::new(mx + 6.0, cy), Align2::LEFT_CENTER, &summary, font(14.0), sc);
                if !c.body.is_empty() && r.right() + 40.0 < mx + 6.0 + max_w {
                    let body = elide(ui, &c.body, &font(13.5), mx + 6.0 + max_w - r.right() - 8.0);
                    painter.text(Pos2::new(r.right() + 8.0, cy), Align2::LEFT_CENTER, body, font(13.5), TEXT_DIM);
                }
                // time separator pill
                let rel = gcc_core::util::relative_time(c.time);
                let next_rel = s.commits.get(ci + 1).map(|n| gcc_core::util::relative_time(n.time));
                if ci == 0 || next_rel.as_ref() != Some(&rel) {
                    if next_rel.is_some() {
                        painter.line_segment([Pos2::new(left, row_rect.bottom()), Pos2::new(left + width, row_rect.bottom())], Stroke::new(1.0, DIVIDER));
                    }
                    let tw = text_width(ui, &rel, font(11.0));
                    let pr = Rect::from_min_size(Pos2::new(left + rows_rect.width() - tw - 22.0, row_rect.bottom() - 7.0), Vec2::new(tw + 12.0, 15.0));
                    painter.rect_filled(pr, Rounding::same(2.0), hex(0x32363F));
                    painter.text(pr.center(), Align2::CENTER_CENTER, rel, font(11.0), hex(0x999B9F));
                }
                if resp.clicked() {
                    self.select(Sel::Commit(ci));
                    self.right = RightView::Details;
                }
                if resp.double_clicked() {
                    if let Some(l) = s.refs.get(&c.id).and_then(|v| v.iter().find(|r| r.kind != RefKind::Tag)) {
                        acts.push(RepoAction::Checkout(l.name.clone()));
                    }
                }
                let oid = c.id;
                let short = c.short.clone();
                let sha = c.id.to_string();
                let msg = c.summary.clone();
                resp.on_hover_text_at_pointer(format!("{} · {} · {}", c.author, gcc_core::util::format_date(c.time), short))
                    .context_menu(|ui| {
                        if ui.button(format!("{}  {}", ic::GIT_BRANCH, t("ctx.create_branch_here"))).clicked() {
                            acts.push(RepoAction::NewBranch(Some(oid)));
                            ui.close_menu();
                        }
                        if ui.button(format!("{}  {}", ic::TAG, t("ctx.create_tag_here"))).clicked() {
                            acts.push(RepoAction::Tag(oid));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.checkout_commit")).clicked() {
                            acts.push(RepoAction::CheckoutCommit(oid));
                            ui.close_menu();
                        }
                        ui.separator();
                        if ui.button(t("ctx.cherry_pick")).clicked() {
                            acts.push(RepoAction::CherryPick(oid));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.revert")).clicked() {
                            acts.push(RepoAction::Revert(oid));
                            ui.close_menu();
                        }
                        ui.menu_button(t("ctx.reset_to"), |ui| {
                            for (k, m) in [("ctx.reset_soft", "soft"), ("ctx.reset_mixed", "mixed"), ("ctx.reset_hard", "hard")] {
                                if ui.button(t(k)).clicked() {
                                    acts.push(RepoAction::Reset(oid, m));
                                    ui.close_menu();
                                }
                            }
                        });
                        ui.separator();
                        if ui.button(format!("{}  {}", ic::SPARKLE, t("ctx.ai_explain"))).clicked() {
                            acts.push(RepoAction::AiExplain(oid));
                            ui.close_menu();
                        }
                        if ui.button(format!("{}  {}", ic::COPY, t("ctx.copy_sha"))).clicked() {
                            acts.push(RepoAction::Copy(sha.clone()));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.copy_message")).clicked() {
                            acts.push(RepoAction::Copy(msg.clone()));
                            ui.close_menu();
                        }
                    });
            }
            // Leave room for horizontal content.
            ui.allocate_space(Vec2::new(width, 0.0));
        });
        if s.truncated {
            let r = Rect::from_min_size(Pos2::new(full.right() - 260.0, full.bottom() - 26.0), Vec2::new(250.0, 20.0));
            ui.painter().text(r.center(), Align2::CENTER_CENTER, tf("graph.truncated", &[&s.commits.len().to_string()]), font(11.5), TEXT_DIM);
        }
    }

    fn panel_header(ui: &mut Ui, title: &str, on_close: &mut bool) {
        let w = ui.available_width();
        let (r, _) = ui.allocate_exact_size(Vec2::new(w, 40.0), Sense::hover());
        ui.painter().rect_filled(r, Rounding::ZERO, hex(0x2E3138));
        ui.painter().text(Pos2::new(r.left() + 14.0, r.center().y), Align2::LEFT_CENTER, title, bold(14.0), TEXT_BRIGHT);
        let xr = Rect::from_center_size(Pos2::new(r.right() - 18.0, r.center().y), Vec2::splat(22.0));
        let resp = ui.interact(xr, ui.id().with(("close", title)), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
        ui.painter().text(xr.center(), Align2::CENTER_CENTER, ic::X, font(15.0), if resp.hovered() { TEXT_BRIGHT } else { TEXT_DIM });
        if resp.clicked() {
            *on_close = true;
        }
    }

    fn commit_panel(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>, ai_on: bool) {
        let Some(d) = self.detail.clone() else { return };
        let mut close = false;
        Self::panel_header(ui, &format!("{} {}", t("detail.commit"), &d.id[..7]), &mut close);
        if close {
            self.select(Sel::None);
            return;
        }
        ScrollArea::vertical().auto_shrink([false, false]).show(ui, |ui| {
            egui::Frame::none().inner_margin(egui::Margin::symmetric(14.0, 10.0)).show(ui, |ui| {
                let mut lines = d.message.trim().splitn(2, '\n');
                let summary = lines.next().unwrap_or("");
                let body = lines.next().unwrap_or("").trim();
                ui.label(egui::RichText::new(summary).font(bold(15.5)).color(TEXT_BRIGHT));
                if !body.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(body).color(TEXT).size(13.0));
                }
                ui.add_space(10.0);
                ui.horizontal(|ui| {
                    let (r, _) = ui.allocate_exact_size(Vec2::splat(32.0), Sense::hover());
                    avatar(ui.painter(), r.center(), 15.0, &d.author);
                    ui.vertical(|ui| {
                        ui.label(egui::RichText::new(&d.author).color(TEXT_BRIGHT).strong());
                        ui.label(egui::RichText::new(format!("{} {}", t("detail.authored"), gcc_core::util::format_date(d.time))).color(TEXT_DIM).size(12.0));
                    });
                });
                ui.add_space(6.0);
                ui.horizontal_wrapped(|ui| {
                    ui.label(egui::RichText::new(t("detail.sha")).color(TEXT_DIM).size(12.0));
                    if ui.link(egui::RichText::new(&d.id[..12]).monospace().size(12.0)).on_hover_text(t("ctx.copy_sha")).clicked() {
                        acts.push(RepoAction::Copy(d.id.clone()));
                    }
                    if !d.parents.is_empty() {
                        ui.label(egui::RichText::new(t("detail.parent")).color(TEXT_DIM).size(12.0));
                        ui.label(egui::RichText::new(d.parents.join(", ")).monospace().size(12.0));
                    }
                });
                ui.add_space(8.0);
                let oid = Oid::from_str(&d.id).ok();
                ui.horizontal(|ui| {
                    let label = format!("{}  {}", ic::SPARKLE, t("detail.explain_ai"));
                    let b = ui.add_enabled(true, egui::Button::new(label).fill(PURPLE_DEEP));
                    if b.clicked() {
                        if let Some(o) = oid {
                            acts.push(RepoAction::AiExplain(o));
                        }
                    }
                    if !ai_on {
                        b.on_hover_text(t("agents.off"));
                    }
                });
                ui.add_space(10.0);
                let adds: usize = d.files.iter().map(|f| f.additions).sum();
                let dels: usize = d.files.iter().map(|f| f.deletions).sum();
                ui.horizontal(|ui| {
                    ui.label(egui::RichText::new(tf("detail.files_changed", &[&d.files.len().to_string()])).color(TEXT).strong());
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        ui.label(egui::RichText::new(format!("-{dels}")).color(DEL_RED));
                        ui.label(egui::RichText::new(format!("+{adds}")).color(ADD_GREEN));
                    });
                });
                ui.add_space(4.0);
                for f in &d.files {
                    if file_row(ui, f, None).clicked() {
                        if let Some(o) = oid {
                            acts.push(RepoAction::ShowDiffCommit(o, f.path.clone()));
                        }
                    }
                }
            });
        });
    }

    fn wip_panel(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>, ai_on: bool) {
        let Some(s) = self.snap.clone() else { return };
        let mut close = false;
        Self::panel_header(ui, &tf("wip.header", &[&s.wip.count().to_string(), &s.head_name]), &mut close);
        if close {
            self.select(Sel::None);
            return;
        }
        let avail_h = ui.available_height();
        let commit_h = 250.0;
        let list_h = (avail_h - commit_h).max(120.0);
        egui::Frame::none().inner_margin(egui::Margin::symmetric(10.0, 6.0)).show(ui, |ui| {
            if s.state != "Clean" {
                egui::Frame::none().fill(hex(0x4A3A1A)).rounding(3.0).inner_margin(6.0).show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.label(egui::RichText::new(format!("{} {}", ic::WARNING, tf("wip.state", &[&s.state]))).color(MOD_YELLOW));
                        if ui.button(t("wip.abort")).clicked() {
                            acts.push(RepoAction::AbortMerge);
                        }
                    });
                });
            }
            ScrollArea::vertical().max_height(list_h).auto_shrink([false, false]).id_source("wip_lists").show(ui, |ui| {
                // Unstaged
                let mut unstaged = s.wip.unstaged.clone();
                for c in &s.wip.conflicted {
                    unstaged.push(git::FileChange { path: c.clone(), old_path: None, status: 'C', additions: 0, deletions: 0 });
                }
                ui.horizontal(|ui| {
                    ui.label(egui::RichText::new(tf("wip.unstaged", &[&unstaged.len().to_string()])).strong().color(TEXT_BRIGHT));
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if !unstaged.is_empty() {
                            if ui.add(egui::Button::new(t("wip.stage_all")).fill(CREATE_GREEN)).clicked() {
                                acts.push(RepoAction::StageAll);
                            }
                            if ui.button(ic::TRASH).on_hover_text(t("wip.discard_all")).clicked() {
                                acts.push(RepoAction::DiscardAll);
                            }
                        }
                    });
                });
                for f in &unstaged {
                    let resp = file_row(ui, f, Some(("wip.stage_file", CREATE_GREEN)));
                    if resp.secondary_clicked() || resp.clicked() {}
                    if resp.clicked() {
                        acts.push(RepoAction::ShowDiffWip(f.path.clone(), false));
                    }
                    let p = f.path.clone();
                    resp.context_menu(|ui| {
                        if ui.button(t("wip.stage_file")).clicked() {
                            acts.push(RepoAction::Stage(vec![p.clone()]));
                            ui.close_menu();
                        }
                        if ui.button(t("wip.discard_file")).clicked() {
                            acts.push(RepoAction::Discard(vec![p.clone()]));
                            ui.close_menu();
                        }
                        if ui.button(t("ctx.copy_name")).clicked() {
                            acts.push(RepoAction::Copy(p.clone()));
                            ui.close_menu();
                        }
                    });
                    if ui.input(|i| i.modifiers.alt) && resp.hovered() {}
                    if resp.middle_clicked() {
                        acts.push(RepoAction::Stage(vec![f.path.clone()]));
                    }
                    if row_action_clicked(ui, &resp) {
                        acts.push(RepoAction::Stage(vec![f.path.clone()]));
                    }
                }
                ui.add_space(8.0);
                ui.horizontal(|ui| {
                    ui.label(egui::RichText::new(tf("wip.staged", &[&s.wip.staged.len().to_string()])).strong().color(TEXT_BRIGHT));
                    ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                        if !s.wip.staged.is_empty() && ui.add(egui::Button::new(t("wip.unstage_all")).fill(hex(0x7A2E2E))).clicked() {
                            acts.push(RepoAction::UnstageAll);
                        }
                    });
                });
                for f in &s.wip.staged {
                    let resp = file_row(ui, f, Some(("wip.unstage_file", hex(0x7A2E2E))));
                    if resp.clicked() {
                        acts.push(RepoAction::ShowDiffWip(f.path.clone(), true));
                    }
                    if row_action_clicked(ui, &resp) {
                        acts.push(RepoAction::Unstage(vec![f.path.clone()]));
                    }
                    let p = f.path.clone();
                    resp.context_menu(|ui| {
                        if ui.button(t("wip.unstage_file")).clicked() {
                            acts.push(RepoAction::Unstage(vec![p.clone()]));
                            ui.close_menu();
                        }
                    });
                }
            });
            // Commit box
            ui.separator();
            ui.horizontal(|ui| {
                ui.label(egui::RichText::new(format!("{} {}", ic::GIT_COMMIT, t("wip.commit"))).strong().color(TEXT_BRIGHT));
                ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                    let r = ui.add_enabled(true, egui::Button::new(format!("{} {}", ic::SPARKLE, t("wip.ai_message"))).fill(PURPLE_DEEP));
                    if r.clicked() {
                        acts.push(RepoAction::AiCommitMessage);
                    }
                    if !ai_on {
                        r.on_hover_text(t("agents.off"));
                    }
                });
            });
            ui.horizontal(|ui| {
                checkbox(ui, &mut self.amend);
                ui.label(egui::RichText::new(t("wip.amend")).size(12.5));
            });
            let w = ui.available_width();
            let resp = ui.add(
                egui::TextEdit::singleline(&mut self.summary)
                    .hint_text(t("wip.summary"))
                    .desired_width(w)
                    .margin(egui::Margin::symmetric(8.0, 6.0)),
            );
            let len = self.summary.chars().count();
            ui.painter().text(
                Pos2::new(resp.rect.right() - 6.0, resp.rect.center().y),
                Align2::RIGHT_CENTER,
                (72i64 - len as i64).to_string(),
                font(11.0),
                if len > 72 { DEL_RED } else { TEXT_FAINT },
            );
            ui.add(
                egui::TextEdit::multiline(&mut self.description)
                    .hint_text(t("wip.description"))
                    .desired_width(w)
                    .desired_rows(4)
                    .margin(egui::Margin::symmetric(8.0, 6.0)),
            );
            ui.add_space(4.0);
            let n = s.wip.staged.len();
            let can = (n > 0 || self.amend || s.state == "Merge") && !self.summary.trim().is_empty();
            let label = if n == 0 && !self.amend { t("wip.stage_first") } else { tf("wip.commit_n", &[&n.to_string()]) };
            if solid_button(ui, &label, CREATE_GREEN, Vec2::new(w, 34.0), can).clicked() {
                acts.push(RepoAction::Commit);
            }
        });
    }

    fn ai_panel(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>, ai_on: bool) {
        let mut close = false;
        Self::panel_header(ui, &format!("{} {}", ic::SPARKLE, t("ai.title")), &mut close);
        if close {
            self.right = RightView::Details;
            return;
        }
        let h = ui.available_height();
        egui::Frame::none().inner_margin(egui::Margin::symmetric(10.0, 6.0)).show(ui, |ui| {
            if !ai_on {
                egui::Frame::none().fill(hex(0x3A3320)).rounding(3.0).inner_margin(8.0).show(ui, |ui| {
                    ui.label(egui::RichText::new(t("ai.not_configured")).color(MOD_YELLOW));
                    if ui.button(t("agents.configure")).clicked() {
                        acts.push(RepoAction::ConfigureAi);
                    }
                });
            }
            ui.horizontal_wrapped(|ui| {
                if let Some(o) = self.selected_oid() {
                    if ui.small_button(t("agents.explain_selected")).clicked() {
                        acts.push(RepoAction::AiExplain(o));
                    }
                }
                if ui.small_button(t("agents.review_wip")).clicked() {
                    acts.push(RepoAction::AiReview);
                }
                if ui.small_button(t("ai.clear")).clicked() {
                    self.ai_msgs.clear();
                }
            });
            ScrollArea::vertical()
                .max_height(h - 130.0)
                .auto_shrink([false, false])
                .stick_to_bottom(true)
                .id_source("ai_chat")
                .show(ui, |ui| {
                    if self.ai_msgs.is_empty() {
                        ui.label(egui::RichText::new(t("ai.empty")).color(TEXT_DIM));
                    }
                    for m in &self.ai_msgs {
                        let user = m.role == "user";
                        let fill = if user { hex(0x2E3D5A) } else { hex(0x30333B) };
                        egui::Frame::none().fill(fill).rounding(4.0).inner_margin(8.0).show(ui, |ui| {
                            ui.set_width(ui.available_width());
                            ui.label(egui::RichText::new(if user { t("ai.you") } else { t("ai.assistant") }).size(11.0).color(TEXT_DIM));
                            let shown: String = if user && m.text.len() > 600 { format!("{}…", &m.text.chars().take(600).collect::<String>()) } else { m.text.clone() };
                            ui.add(egui::Label::new(egui::RichText::new(shown).color(TEXT_BRIGHT).size(13.0)).selectable(true));
                            if !user && ui.small_button(format!("{} {}", ic::COPY, t("ai.copy"))).clicked() {
                                acts.push(RepoAction::Copy(m.text.clone()));
                            }
                        });
                        ui.add_space(6.0);
                    }
                    if self.ai_busy {
                        ui.horizontal(|ui| {
                            ui.spinner();
                            ui.label(egui::RichText::new(if self.ai_status.is_empty() { t("ai.thinking") } else { self.ai_status.clone() }).color(TEXT_DIM));
                        });
                    }
                });
            ui.separator();
            let w = ui.available_width();
            let resp = ui.add(
                egui::TextEdit::multiline(&mut self.ai_input)
                    .hint_text(t("ai.ask_hint"))
                    .desired_width(w)
                    .desired_rows(2),
            );
            let send_key = resp.has_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter) && !i.modifiers.shift);
            let send = ui
                .add_enabled(!self.ai_busy, egui::Button::new(format!("{} {}", ic::PAPER_PLANE_RIGHT, t("ai.send"))).fill(PURPLE_DEEP))
                .clicked();
            if (send || send_key) && !self.ai_input.trim().is_empty() && !self.ai_busy {
                let q = self.ai_input.trim().to_string();
                self.ai_input.clear();
                acts.push(RepoAction::AiAsk(q));
            }
        });
    }

    fn diff_view(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>) {
        let Some(d) = self.diff.clone() else { return };
        let full = ui.max_rect();
        let hdr = Rect::from_min_size(full.min, Vec2::new(full.width(), 36.0));
        ui.painter().rect_filled(hdr, Rounding::ZERO, PANEL);
        ui.painter().text(Pos2::new(hdr.left() + 12.0, hdr.center().y), Align2::LEFT_CENTER, &d.title, bold(14.0), TEXT_BRIGHT);
        let mut child = ui.child_ui(hdr.shrink2(Vec2::new(10.0, 4.0)), Layout::right_to_left(Align::Center), None);
        if child.button(format!("{} {}", ic::X, t("diff.close"))).clicked() {
            self.diff = None;
            return;
        }
        match d.staged {
            Some(false) => {
                if child.add(egui::Button::new(t("wip.stage_file")).fill(CREATE_GREEN)).clicked() {
                    acts.push(RepoAction::Stage(vec![d.file.clone()]));
                }
            }
            Some(true) => {
                if child.add(egui::Button::new(t("wip.unstage_file")).fill(hex(0x7A2E2E))).clicked() {
                    acts.push(RepoAction::Unstage(vec![d.file.clone()]));
                }
            }
            None => {}
        }
        let adds = d.lines.iter().filter(|l| l.kind == DiffLineKind::Add).count();
        let dels = d.lines.iter().filter(|l| l.kind == DiffLineKind::Del).count();
        child.label(egui::RichText::new(format!("-{dels}")).color(DEL_RED));
        child.label(egui::RichText::new(format!("+{adds}")).color(ADD_GREEN));

        let body = Rect::from_min_max(Pos2::new(full.left(), hdr.bottom()), full.max);
        let mut child = ui.child_ui(body, Layout::top_down(Align::Min), None);
        let lh = 18.0;
        if d.lines.is_empty() {
            child.add_space(20.0);
            child.label(egui::RichText::new(t("diff.binary_or_empty")).color(TEXT_DIM));
            return;
        }
        ScrollArea::both().auto_shrink([false, false]).id_source("diff_scroll").show_rows(&mut child, lh, d.lines.len(), |ui, range| {
            let origin = ui.min_rect().min;
            let w = body.width().max(ui.available_width());
            let p = ui.painter().clone();
            let mut maxw: f32 = w;
            for i in range.clone() {
                let l = &d.lines[i];
                let y = origin.y + (i - range.start) as f32 * lh;
                let r = Rect::from_min_size(Pos2::new(body.left(), y), Vec2::new(w, lh));
                let (bg, fg, sign) = match l.kind {
                    DiffLineKind::Add => (hex(0x1E3A2A), hex(0xBFE9C9), "+"),
                    DiffLineKind::Del => (hex(0x45232A), hex(0xF2C0C4), "-"),
                    DiffLineKind::Hunk => (hex(0x262B38), hex(0x8EA6D8), ""),
                    _ => (CONTENT, TEXT, " "),
                };
                p.rect_filled(r, Rounding::ZERO, bg);
                let num = |n: Option<u32>| n.map(|x| x.to_string()).unwrap_or_default();
                if l.kind != DiffLineKind::Hunk {
                    p.text(Pos2::new(r.left() + 38.0, r.center().y), Align2::RIGHT_CENTER, num(l.old_no), mono(11.5), TEXT_FAINT);
                    p.text(Pos2::new(r.left() + 78.0, r.center().y), Align2::RIGHT_CENTER, num(l.new_no), mono(11.5), TEXT_FAINT);
                    p.text(Pos2::new(r.left() + 88.0, r.center().y), Align2::LEFT_CENTER, sign, mono(12.5), fg);
                }
                let text = l.text.replace('\t', "    ");
                let tr = p.text(Pos2::new(r.left() + if l.kind == DiffLineKind::Hunk { 10.0 } else { 102.0 }, r.center().y), Align2::LEFT_CENTER, text, mono(12.5), fg);
                maxw = maxw.max(tr.right() - body.left() + 20.0);
            }
            ui.allocate_space(Vec2::new(maxw, 0.0));
        });
    }

    fn terminal(&mut self, ui: &mut Ui, acts: &mut Vec<RepoAction>) {
        ui.horizontal(|ui| {
            ui.label(egui::RichText::new(format!("{} {}", ic::TERMINAL_WINDOW, t("terminal.title"))).strong());
            ui.label(egui::RichText::new(self.path.display().to_string()).color(TEXT_DIM).size(12.0));
            ui.with_layout(Layout::right_to_left(Align::Center), |ui| {
                if ui.small_button(ic::X).clicked() {
                    self.terminal_open = false;
                }
                if ui.small_button(t("terminal.clear")).clicked() {
                    self.term_output.clear();
                }
                if ui.small_button(t("toolbar.open_external_terminal")).clicked() {
                    acts.push(RepoAction::OpenTerminal);
                }
            });
        });
        let h = ui.available_height() - 34.0;
        ScrollArea::vertical().max_height(h.max(40.0)).auto_shrink([false, false]).stick_to_bottom(true).id_source("term_out").show(ui, |ui| {
            ui.add(egui::Label::new(egui::RichText::new(&self.term_output).font(mono(12.5)).color(hex(0xC8E1C8))).selectable(true));
        });
        ui.horizontal(|ui| {
            ui.label(egui::RichText::new("$").font(mono(13.0)).color(CHECK_GREEN));
            let w = ui.available_width();
            let resp = ui.add(egui::TextEdit::singleline(&mut self.term_input).font(mono(13.0)).desired_width(w).hint_text(t("terminal.hint")));
            if resp.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter)) {
                let line = std::mem::take(&mut self.term_input);
                if !line.trim().is_empty() {
                    acts.push(RepoAction::RunTerminal(line));
                }
                resp.request_focus();
            }
        });
    }
}

fn dashed_circle(p: &egui::Painter, c: Pos2, r: f32, color: Color32) {
    let n = 16;
    for i in 0..n {
        if i % 2 == 0 {
            let a0 = i as f32 / n as f32 * std::f32::consts::TAU;
            let a1 = (i + 1) as f32 / n as f32 * std::f32::consts::TAU;
            p.line_segment(
                [c + Vec2::angled(a0) * r, c + Vec2::angled(a1) * r],
                Stroke::new(2.0, color),
            );
        }
    }
}

/// One file in a list: status icon, folder (dim) and name. With `action`, a small
/// button appears on hover (stage / unstage).
fn file_row(ui: &mut Ui, f: &git::FileChange, action: Option<(&str, Color32)>) -> egui::Response {
    let w = ui.available_width();
    let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 24.0), Sense::click());
    let p = ui.painter();
    if resp.hovered() {
        p.rect_filled(r, Rounding::same(2.0), hex(0x323641));
    }
    let col = status_color(f.status);
    p.text(Pos2::new(r.left() + 10.0, r.center().y), Align2::CENTER_CENTER, status_icon(f.status), font(13.0), col);
    let (dir, name) = match f.path.rsplit_once('/') {
        Some((d, n)) => (format!("{d}/"), n.to_string()),
        None => (String::new(), f.path.clone()),
    };
    let mut right = r.right() - 6.0;
    if f.additions + f.deletions > 0 {
        let rr = p.text(Pos2::new(right, r.center().y), Align2::RIGHT_CENTER, format!("+{} -{}", f.additions, f.deletions), font(11.0), TEXT_DIM);
        right = rr.left() - 6.0;
    }
    if let (Some((key, fill)), true) = (action, resp.hovered()) {
        let label = t(key);
        let bw = text_width(ui, &label, font(11.5)) + 14.0;
        let br = Rect::from_min_size(Pos2::new(right - bw, r.top() + 3.0), Vec2::new(bw, 18.0));
        p.rect_filled(br, Rounding::same(2.0), fill);
        p.text(br.center(), Align2::CENTER_CENTER, label, font(11.5), TEXT_BRIGHT);
        right = br.left() - 6.0;
    }
    let x = r.left() + 22.0;
    let nw = text_width(ui, &name, font(13.0));
    let avail = right - x;
    if nw >= avail || dir.is_empty() {
        let n = elide(ui, &name, &font(13.0), avail);
        p.text(Pos2::new(x, r.center().y), Align2::LEFT_CENTER, n, font(13.0), TEXT_BRIGHT);
    } else {
        let d = elide(ui, &dir, &font(13.0), avail - nw);
        let dr = p.text(Pos2::new(x, r.center().y), Align2::LEFT_CENTER, d, font(13.0), TEXT_DIM);
        p.text(Pos2::new(dr.right(), r.center().y), Align2::LEFT_CENTER, name, font(13.0), TEXT_BRIGHT);
    }
    resp.on_hover_text(f.old_path.as_ref().map(|o| format!("{o} → {}", f.path)).unwrap_or_else(|| f.path.clone()))
}

/// True when the click landed on the hover button at the right of a file row.
fn row_action_clicked(ui: &Ui, resp: &egui::Response) -> bool {
    if !resp.clicked() {
        return false;
    }
    let pos = ui.input(|i| i.pointer.interact_pos());
    match pos {
        Some(p) => p.x > resp.rect.right() - 110.0,
        None => false,
    }
}

/// A short text that changes whenever HEAD, a ref or the index changes.
pub fn fingerprint(path: &std::path::Path) -> String {
    let Ok(repo) = git2::Repository::open(path) else { return String::new() };
    let mut s = String::new();
    if let Ok(h) = repo.head() {
        s.push_str(&format!("{:?}{:?}", h.name(), h.target()));
    }
    if let Ok(refs) = repo.references() {
        for r in refs.flatten() {
            s.push_str(r.name().unwrap_or(""));
            if let Some(t) = r.target() {
                s.push_str(&t.to_string()[..8]);
            }
        }
    }
    if let Ok(st) = repo.statuses(Some(git2::StatusOptions::new().include_untracked(true).recurse_untracked_dirs(true))) {
        for e in st.iter() {
            s.push_str(e.path().unwrap_or(""));
            s.push_str(&format!("{}", e.status().bits()));
        }
    }
    if let Ok(m) = std::fs::metadata(repo.path().join("index")).and_then(|m| m.modified()) {
        s.push_str(&format!("{m:?}"));
    }
    s
}

