//! A repository tab: toolbar, left panel, commit graph, details / WIP panel,
//! diff view, AI chat and the small terminal.

use super::theme::*;
use eframe::egui::{
    self, Align, Align2, Color32, CursorIcon, Layout, Pos2, Rect, Rounding, ScrollArea, Sense, Stroke, Ui, Vec2,
};
use egui_phosphor::regular as ic;
use gcc_core::ai::ChatMessage;
use gcc_core::config::{PullMode, Settings};
