    Merge(String),
    CherryPick(Oid),
    Revert(Oid),
    Reset(Oid, &'static str),
    Tag(Oid),
    DeleteTag(String),
    Stage(Vec<String>),
    Unstage(Vec<String>),
    StageAll,
    UnstageAll,
    Discard(Vec<String>),
    DiscardAll,
    Commit,
    OpenTerminal,
    OpenFolder,
    OpenEditor,
    AiExplain(Oid),
    AiReview,
    AiCommitMessage,
    AiAsk(String),
    Copy(String),
    SwitchRepo(String),
    OpenRepo,
    AbortMerge,
    AddRemote,
    RemoveRemote(String),
    ShowDiffCommit(Oid, String),
    ShowDiffWip(String, bool),
    RunTerminal(String),
    ConfigureAi,
