    fn tab_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::top("tabs")
            .exact_height(36.0)
            .frame(egui::Frame::none().fill(TAB_BAR))
            .show(ctx, |ui| {
                let rect = ui.max_rect();
                let p = ui.painter().clone();
                // Folder button (repository management)
                let fr = Rect::from_min_size(rect.min, Vec2::new(36.0, rect.height()));
                let fresp = ui.interact(fr, ui.id().with("folder"), Sense::click()).on_hover_text(t("menu.repo_management"));
                if fresp.hovered() {
                    p.rect_filled(fr, Rounding::ZERO, hex(0x33373F));
                }
                p.text(fr.center(), Align2::CENTER_CENTER, ic::FOLDER_SIMPLE, font(17.0), TEXT);
                if fresp.clicked() {
                    self.new_tab();
                }
                let mut x = fr.right() + 4.0;
                let mut close: Option<usize> = None;
                let mut activate: Option<usize> = None;
                let right_limit = rect.right() - 260.0;
                for (i, tab) in self.tabs.iter().enumerate() {
                    let title = tab.title();
                    let icon = tab.icon();
                    let active = i == self.active;
                    let f = bold(15.0);
                    let tw = text_width(ui, &title, f.clone());
                    let iw = if icon.is_empty() { 0.0 } else { 18.0 };
                    let cw = if active { 20.0 } else { 0.0 };
                    let w = (tw + iw + cw + 40.0).clamp(80.0, 230.0);
                    if x + w > right_limit {
                        break;
                    }
                    let r = Rect::from_min_size(Pos2::new(x, rect.top()), Vec2::new(w, rect.height()));
                    let resp = ui.interact(r, ui.id().with(("tab", tab.id)), Sense::click());
                    if active {
                        p.rect_filled(r, Rounding::ZERO, TAB_ACTIVE);
                    } else if resp.hovered() {
                        p.rect_filled(r, Rounding::ZERO, hex(0x30333B));
                    }
                    let col = if active { TEXT_BRIGHT } else { hex(0xA3A7AE) };
                    let mut tx = r.left() + 20.0;
                    if !icon.is_empty() {
                        p.text(Pos2::new(tx, r.center().y), Align2::LEFT_CENTER, icon, font(13.0), col);
                        tx += iw;
                    }
                    let name = elide(ui, &title, &f, r.right() - tx - cw - 14.0);
                    p.text(Pos2::new(tx, r.center().y), Align2::LEFT_CENTER, name, f, col);
                    if active {
                        let cr = Rect::from_center_size(Pos2::new(r.right() - 16.0, r.center().y), Vec2::splat(16.0));
                        let cresp = ui.interact(cr, ui.id().with(("close", tab.id)), Sense::click());
                        p.text(cr.center(), Align2::CENTER_CENTER, ic::X, font(13.0), if cresp.hovered() { TEXT_BRIGHT } else { TEXT });
                        if cresp.clicked() {
                            close = Some(i);
                        }
                    }
                    if resp.clicked() {
                        activate = Some(i);
                    }
                    if resp.middle_clicked() {
                        close = Some(i);
                    }
                    let next_active = i + 1 == self.active;
                    if !active && !next_active {
                        p.line_segment(
                            [Pos2::new(r.right(), r.top() + 8.0), Pos2::new(r.right(), r.bottom() - 8.0)],
                            Stroke::new(1.0, hex(0x40444C)),
                        );
                    }
                    x += w;
                }
                // "+" new tab
                let pr = Rect::from_min_size(Pos2::new(x + 2.0, rect.top()), Vec2::new(30.0, rect.height()));
                let presp = ui.interact(pr, ui.id().with("plus"), Sense::click()).on_hover_text(t("menu.new_tab"));
                p.text(pr.center(), Align2::CENTER_CENTER, ic::PLUS, font(16.0), if presp.hovered() { TEXT_BRIGHT } else { TEXT });
                if presp.clicked() {
                    self.new_tab();
                }
                if let Some(i) = activate {
                    self.active = i;
                    if self.screen == Screen::Prefs {
                        self.screen = Screen::Main;
                    }
                }
                if let Some(i) = close {
                    self.close_tab(i);
                }

                // Right side: tab list, bell, gear, profile
                let mut rx = rect.right() - 10.0;
                let prof_label = self.settings.profile().name.clone();
                let lw = text_width(ui, &prof_label, font(13.5));
                let pw = lw + 46.0;
                let prr = Rect::from_min_size(Pos2::new(rx - pw, rect.top() + 4.0), Vec2::new(pw, rect.height() - 8.0));
                let prresp = ui.interact(prr, ui.id().with("profile"), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
                p.rect_filled(prr, Rounding::same(3.0), if prresp.hovered() || self.profile_open { hex(0x3A4252) } else { hex(0x2F3644) });
                pixel_avatar(&p, Rect::from_center_size(Pos2::new(prr.left() + 14.0, prr.center().y), Vec2::splat(20.0)));
                p.text(Pos2::new(prr.left() + 28.0, prr.center().y), Align2::LEFT_CENTER, &prof_label, font(13.5), TEXT_BRIGHT);
                p.text(Pos2::new(prr.right() - 8.0, prr.center().y), Align2::CENTER_CENTER, "▾", font(11.0), TEXT_BRIGHT);
                if prresp.clicked() {
                    self.profile_open = !self.profile_open;
                    self.bell_open = false;
                }
                rx = prr.left() - 8.0;
                let gr = Rect::from_center_size(Pos2::new(rx - 12.0, rect.center().y), Vec2::splat(26.0));
                let gresp = ui.interact(gr, ui.id().with("gear"), Sense::click()).on_hover_text(t("menu.preferences"));
                p.text(gr.center(), Align2::CENTER_CENTER, ic::GEAR, font(19.0), if gresp.hovered() { TEXT_BRIGHT } else { TEXT });
                if gresp.clicked() {
                    self.open_prefs(PrefPage::General);
                }
                rx = gr.left() - 6.0;
                let br = Rect::from_center_size(Pos2::new(rx - 12.0, rect.center().y), Vec2::splat(26.0));
                let bresp = ui.interact(br, ui.id().with("bell"), Sense::click()).on_hover_text(t("notify.title"));
                p.text(br.center(), Align2::CENTER_CENTER, ic::BELL, font(19.0), if bresp.hovered() { TEXT_BRIGHT } else { TEXT });
                if self.unread > 0 {
                    let bc = br.center() + Vec2::new(7.0, -7.0);
                    p.circle_filled(bc, 6.5, BADGE_BLUE);
                    p.text(bc, Align2::CENTER_CENTER, self.unread.min(9).to_string(), bold(9.0), egui::Color32::WHITE);
                }
                if bresp.clicked() {
                    self.bell_open = !self.bell_open;
                    self.profile_open = false;
                    self.unread = 0;
                }
                rx = br.left() - 8.0;
                let dr = Rect::from_center_size(Pos2::new(rx - 12.0, rect.center().y), Vec2::splat(26.0));
                let dresp = ui.interact(dr, ui.id().with("tablist"), Sense::click()).on_hover_text(t("tabs.all"));
                p.text(dr.center(), Align2::CENTER_CENTER, ic::CARET_DOWN, font(18.0), if dresp.hovered() { TEXT_BRIGHT } else { TEXT });
                if dresp.clicked() {
                    self.tabs_open = !self.tabs_open;
                }
                let anchor_tabs = Pos2::new(dr.right(), rect.bottom());
                let anchor_bell = Pos2::new(br.right() + 40.0, rect.bottom());
                let anchor_prof = Pos2::new(prr.right(), rect.bottom());
                self.popups(ctx, anchor_tabs, anchor_bell, anchor_prof);
            });
    }

    fn popups(&mut self, ctx: &egui::Context, tabs_at: Pos2, bell_at: Pos2, prof_at: Pos2) {
        let click_outside = |ctx: &egui::Context, r: Rect| {
            ctx.input(|i| i.pointer.any_pressed() && i.pointer.interact_pos().map(|p| !r.contains(p)).unwrap_or(false))
        };
        if self.tabs_open {
            let area = egui::Area::new(egui::Id::new("tabs_popup"))
                .order(egui::Order::Foreground)
                .pivot(Align2::RIGHT_TOP)
                .fixed_pos(tabs_at)
                .show(ctx, |ui| {
                    egui::Frame::popup(ui.style()).fill(POPUP).show(ui, |ui| {
                        ui.set_min_width(240.0);
                        let mut go = None;
                        for (i, tab) in self.tabs.iter().enumerate() {
                            if ui.selectable_label(i == self.active, format!("{} {}", tab.icon(), tab.title())).clicked() {
                                go = Some(i);
                            }
                        }
                        if let Some(i) = go {
                            self.active = i;
                            self.tabs_open = false;
                        }
                    });
                });
            if click_outside(ctx, area.response.rect) && !ctx.is_using_pointer() && area.response.rect.width() > 0.0 && self.frame % 1 == 0 {
                // close when clicking elsewhere (but not on the toggle itself)
                let p = ctx.input(|i| i.pointer.interact_pos()).unwrap_or_default();
                if p.y > 92.0 || p.x < tabs_at.x - 30.0 {
                    self.tabs_open = false;
                }
            }
        }
        if self.bell_open {
            let area = egui::Area::new(egui::Id::new("bell_popup"))
                .order(egui::Order::Foreground)
                .pivot(Align2::RIGHT_TOP)
                .fixed_pos(bell_at)
                .show(ctx, |ui| {
                    egui::Frame::popup(ui.style()).fill(POPUP).show(ui, |ui| {
                        ui.set_width(360.0);
                        ui.label(egui::RichText::new(t("notify.title")).font(bold(15.0)).color(TEXT_BRIGHT));
                        ui.separator();
                        if self.notifications.is_empty() {
                            ui.label(egui::RichText::new(t("notify.none")).color(TEXT_DIM));
                        }
                        egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                            for (n, err) in &self.notifications {
                                let c = if *err { DEL_RED } else { TEXT };
                                ui.label(egui::RichText::new(format!("{} {}", if *err { ic::WARNING } else { ic::INFO }, n)).color(c));
                                ui.add_space(2.0);
                            }
                        });
                        if !self.notifications.is_empty() && ui.small_button(t("notify.clear")).clicked() {
                            self.notifications.clear();
                        }
                    });
                });
            let p = ctx.input(|i| i.pointer.interact_pos()).unwrap_or_default();
            if click_outside(ctx, area.response.rect) && p.y > 92.0 {
                self.bell_open = false;
            }
        }
        if self.profile_open {
            let area = egui::Area::new(egui::Id::new("profile_popup"))
                .order(egui::Order::Foreground)
                .pivot(Align2::RIGHT_TOP)
                .fixed_pos(prof_at + Vec2::new(10.0, 0.0))
                .show(ctx, |ui| self.profile_popup(ui));
            let p = ctx.input(|i| i.pointer.interact_pos()).unwrap_or_default();
            if click_outside(ctx, area.response.rect) && p.y > 92.0 {
                self.profile_open = false;
            }
        }
    }

    fn profile_popup(&mut self, ui: &mut egui::Ui) {
        egui::Frame::none()
            .fill(POPUP)
            .rounding(Rounding::same(3.0))
            .shadow(ui.style().visuals.popup_shadow)
            .inner_margin(egui::Margin::symmetric(0.0, 8.0))
            .show(ui, |ui| {
                ui.set_width(330.0);
                let pad = |ui: &mut egui::Ui, f: &mut dyn FnMut(&mut egui::Ui)| {
                    egui::Frame::none().inner_margin(egui::Margin::symmetric(20.0, 2.0)).show(ui, |ui| f(ui));
                };
                pad(ui, &mut |ui| {
                    ui.label(egui::RichText::new(t("profile.current")).font(bold(14.5)).color(TEXT_BRIGHT));
                });
                ui.separator();
                let mut switch_to = None;
                for (i, pr) in self.settings.profiles.iter().enumerate() {
                    egui::Frame::none().inner_margin(egui::Margin::symmetric(20.0, 2.0)).show(ui, |ui| {
                        let w = ui.available_width();
                        let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 38.0), Sense::click());
                        let sel = i == self.settings.active_profile;
                        if sel {
                            ui.painter().rect_filled(r, Rounding::ZERO, hex(0x464B56));
                        } else if resp.hovered() {
                            ui.painter().rect_filled(r, Rounding::ZERO, hex(0x434852));
                        }
                        pixel_avatar(ui.painter(), Rect::from_center_size(Pos2::new(r.left() + 24.0, r.center().y), Vec2::splat(26.0)));
                        ui.painter().text(Pos2::new(r.left() + 48.0, r.center().y), Align2::LEFT_CENTER, &pr.name, font(14.5), TEXT_BRIGHT);
                        if resp.clicked() {
                            switch_to = Some(i);
                        }
                    });
                }
                if let Some(i) = switch_to {
                    self.settings.active_profile = i;
                    self.engine = make_engine(&self.settings);
                    self.save_settings();
                }
                pad(ui, &mut |ui| {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(t("profile.ai_assistant")).size(12.5).color(TEXT_DIM));
                    let ai = &self.settings.ai;
                    let status = match ai.mode {
                        AiMode::Off => t("profile.ai_off"),
                        AiMode::Api => format!("{} · {}", ai.api_kind.label(), ai.model),
                        AiMode::Acp => format!("ACP · {}", ai.acp_command),
                    };
                    ui.label(egui::RichText::new(status).size(13.0).color(TEXT));
                    ui.add_space(6.0);
                    ui.label(egui::RichText::new(t("profile.signature")).size(12.5).color(TEXT_DIM));
                    let p = self.settings.profile();
                    let name = if p.user_name.is_empty() { t("profile.not_set") } else { p.user_name.clone() };
                    ui.label(egui::RichText::new(name).size(14.0).color(TEXT_BRIGHT));
                    ui.label(egui::RichText::new(&p.user_email).size(12.0).color(TEXT));
                    ui.add_space(6.0);
                });
                let mut go: Option<PrefPage> = None;
                for (icon, key, page) in [
                    (ic::USER_GEAR, "profile.manage", PrefPage::Profiles),
                    (ic::SPARKLE, "profile.configure_ai", PrefPage::Ai),
                    (ic::TRANSLATE, "profile.language", PrefPage::Language),
                    (ic::DOWNLOAD_SIMPLE, "profile.download_git", PrefPage::Git),
                ] {
                    egui::Frame::none().inner_margin(egui::Margin::symmetric(20.0, 0.0)).show(ui, |ui| {
                        let w = ui.available_width();
                        let (r, resp) = ui.allocate_exact_size(Vec2::new(w, 34.0), Sense::click());
                        if resp.hovered() {
                            ui.painter().rect_filled(r, Rounding::ZERO, hex(0x434852));
                        }
                        ui.painter().text(Pos2::new(r.left() + 10.0, r.center().y), Align2::CENTER_CENTER, icon, font(16.0), TEXT_DIM);
                        ui.painter().text(Pos2::new(r.left() + 30.0, r.center().y), Align2::LEFT_CENTER, t(key), font(14.5), TEXT_BRIGHT);
                        if resp.clicked() {
                            go = Some(page);
                        }
                    });
                }
                if let Some(p) = go {
                    self.profile_open = false;
                    self.open_prefs(p);
                }
            });
    }

    fn status_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::bottom("status")
            .exact_height(24.0)
            .frame(egui::Frame::none().fill(PANEL))
            .show(ctx, |ui| {
                self.status_drawn = true;
                let rect = ui.max_rect();
                let p = ui.painter().clone();
                p.line_segment([rect.left_top(), rect.right_top()], Stroke::new(1.0, hex(0x1A1C20)));
                let cy = rect.center().y;
                // Left: latest notification / git status
                let (left_icon, left_text, col) = if let Some(j) = self.jobs.first() {
                    let pr = j.progress.lock().map(|v| *v).unwrap_or(0.0);
                    (ic::CIRCLE_NOTCH, format!("{} {:.0}%", j.title, pr * 100.0), TEXT)
                } else if self.engine.cli.is_none() {
                    (ic::WARNING, t("status.builtin_engine"), MOD_YELLOW)
                } else if let Some((n, e)) = self.notifications.first() {
                    (if *e { ic::WARNING } else { ic::INFO }, n.clone(), if *e { MOD_YELLOW } else { TEXT })
                } else {
                    (ic::CHECK, t("status.ready"), TEXT)
                };
                p.text(Pos2::new(rect.left() + 26.0, cy), Align2::CENTER_CENTER, left_icon, font(14.0), col);
                let lt = elide(ui, &left_text, &font(13.0), rect.width() * 0.35);
                p.text(Pos2::new(rect.left() + 42.0, cy), Align2::LEFT_CENTER, lt, font(13.0), TEXT);
                // Centre: Git version / download link
                let center_text = match &self.git_version {
                    Some(v) => tf("status.git_version", &[v]),
                    None => t("status.download_git"),
                };
                let cw = text_width(ui, &center_text, font(13.0));
                let cr = Rect::from_center_size(Pos2::new(rect.center().x, cy), Vec2::new(cw, 20.0));
                let cresp = ui.interact(cr, ui.id().with("gitver"), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
                p.text(cr.center(), Align2::CENTER_CENTER, &center_text, font(13.0), if cresp.hovered() { LINK_SOFT } else { LINK });
                if cresp.clicked() {
                    self.open_prefs(PrefPage::Git);
                }
                // Right: icons, zoom, help, logo, version
                let mut x = rect.right() - 8.0;
                let ver = format!("{}", gcc_core::config::APP_VERSION);
                let vw = text_width(ui, &ver, mono(12.0)) + 12.0;
                let vr = Rect::from_min_size(Pos2::new(x - vw, rect.top() + 3.0), Vec2::new(vw, 18.0));
                p.rect(vr, Rounding::same(2.0), hex(0x1F2227), Stroke::new(1.0, hex(0x3A3F49)));
                p.text(vr.center(), Align2::CENTER_CENTER, ver, mono(12.0), TEXT);
                x = vr.left() - 14.0;
                logo(&p, Pos2::new(x, cy), 15.0, hex(0x6FD3C3));
                x -= 18.0;
                let help = t("status.help");
                let hw = text_width(ui, &help, font(13.0));
                let hr = Rect::from_min_size(Pos2::new(x - hw, rect.top()), Vec2::new(hw, rect.height()));
                let hresp = ui.interact(hr, ui.id().with("help"), Sense::click()).on_hover_cursor(CursorIcon::PointingHand);
                p.text(Pos2::new(hr.right(), cy), Align2::RIGHT_CENTER, &help, font(13.0), if hresp.hovered() { LINK_SOFT } else { LINK });
                if hresp.clicked() {
                    self.add_tab(TabKind::Guide, true);
                }
                x = hr.left() - 18.0;
                let z = format!("{:.0}%", self.settings.zoom * 100.0);
                let zw = text_width(ui, &z, font(13.0));
                let zr = Rect::from_min_size(Pos2::new(x - zw - 20.0, rect.top()), Vec2::new(zw + 20.0, rect.height()));
                let zresp = ui.interact(zr, ui.id().with("zoom"), Sense::click()).on_hover_text(t("status.zoom_hint"));
                p.text(Pos2::new(zr.left() + 7.0, cy), Align2::CENTER_CENTER, ic::MAGNIFYING_GLASS_PLUS, font(14.0), TEXT);
                p.text(Pos2::new(zr.right(), cy), Align2::RIGHT_CENTER, z, font(13.0), TEXT_BRIGHT);
                if zresp.clicked() {
                    self.set_zoom(1.0);
                }
                x = zr.left() - 22.0;
                let kr = Rect::from_center_size(Pos2::new(x, cy), Vec2::splat(20.0));
                let kresp = ui.interact(kr, ui.id().with("keys"), Sense::click()).on_hover_text(t("menu.shortcuts"));
                p.text(kr.center(), Align2::CENTER_CENTER, ic::KEYBOARD, font(16.0), TEXT);
                if kresp.clicked() {
                    self.modal = Some(Modal::Shortcuts);
                }
                x -= 30.0;
                let lr = Rect::from_center_size(Pos2::new(x, cy), Vec2::splat(20.0));
                let lresp = ui.interact(lr, ui.id().with("activity"), Sense::click()).on_hover_text(t("notify.title"));
                p.text(lr.center(), Align2::CENTER_CENTER, ic::LIST_BULLETS, font(16.0), TEXT);
                if lresp.clicked() {
                    self.bell_open = !self.bell_open;
                }
            });
    }

    fn toasts_ui(&mut self, ctx: &egui::Context) {
        let now = ctx.input(|i| i.time);
        self.toasts.retain(|t| t.until > now);
        let screen = ctx.screen_rect();
        let mut y = screen.bottom() - 34.0;
        // Running jobs: blue progress cards (bottom-left), like the reference's clone card.
        let jobs: Vec<(String, f32)> = self.jobs.iter().map(|j| (j.title.clone(), j.progress.lock().map(|v| *v).unwrap_or(0.0))).collect();
        for (i, (title, pr)) in jobs.iter().enumerate() {
            let h = 108.0;
            let r = Rect::from_min_size(Pos2::new(screen.left() + 14.0, y - h), Vec2::new(352.0, h));
            egui::Area::new(egui::Id::new(("job", i))).order(egui::Order::Foreground).fixed_pos(r.min).show(ctx, |ui| {
                let p = ui.painter();
                p.rect_filled(r, Rounding::same(2.0), TOAST_BG);
                p.rect_filled(Rect::from_min_size(r.min, Vec2::new(36.0, h)), Rounding::same(2.0), TOAST_BLUE);
                let c = Pos2::new(r.left() + 18.0, r.center().y);
                let ang = now as f32 * 4.0;
                for k in 0..8 {
                    let a = ang + k as f32 * 0.6;
                    let al = (k as f32 / 8.0 * 255.0) as u8;
                    p.circle_filled(c + Vec2::angled(a) * 8.0, 1.6, egui::Color32::from_white_alpha(al));
                }
                let galley = ui.fonts(|f| f.layout(title.clone(), font(16.5), TEXT_BRIGHT, 270.0));
                p.galley(Pos2::new(r.left() + 52.0, r.top() + 16.0), galley, TEXT_BRIGHT);
                let bar = Rect::from_min_size(Pos2::new(r.left() + 52.0, r.bottom() - 30.0), Vec2::new(284.0, 18.0));
                p.rect_filled(bar, Rounding::same(2.0), hex(0xF2F2F2));
                let fill_w = (bar.width() * pr.max(0.05)).min(bar.width());
                p.rect_filled(Rect::from_min_size(bar.min, Vec2::new(fill_w, bar.height())), Rounding::same(2.0), hex(0x5B8BD8));
                let _ = ui.allocate_exact_size(r.size(), Sense::hover());
            });
            y -= h + 8.0;
            ctx.request_repaint();
        }
        let toasts: Vec<(String, bool)> = self.toasts.iter().map(|t| (t.text.clone(), t.error)).collect();
        let mut ty = screen.bottom() - 34.0;
        for (i, (text, err)) in toasts.iter().enumerate().rev() {
            let galley = ctx.fonts(|f| f.layout(text.clone(), font(13.5), TEXT_BRIGHT, 360.0));
            let h = galley.size().y + 22.0;
            let r = Rect::from_min_size(Pos2::new(screen.right() - 420.0, ty - h), Vec2::new(400.0, h));
            egui::Area::new(egui::Id::new(("toast", i))).order(egui::Order::Foreground).fixed_pos(r.min).show(ctx, |ui| {
                let p = ui.painter();
                p.rect_filled(r, Rounding::same(3.0), TOAST_BG);
                p.rect_filled(Rect::from_min_size(r.min, Vec2::new(5.0, h)), Rounding::same(2.0), if *err { DEL_RED } else { CHECK_GREEN });
                p.galley(Pos2::new(r.left() + 20.0, r.top() + 11.0), galley.clone(), TEXT_BRIGHT);
                let resp = ui.allocate_exact_size(r.size(), Sense::click()).1;
                if resp.clicked() {
                    self.toasts.retain(|t| &t.text != text);
                }
            });
            ty -= h + 8.0;
        }
        if !self.toasts.is_empty() {
            ctx.request_repaint_after(std::time::Duration::from_millis(500));
        }
    }

    fn central(&mut self, ctx: &egui::Context) {
        egui::CentralPanel::default().frame(egui::Frame::none().fill(CONTENT)).show(ctx, |ui| {
            if self.screen == Screen::Prefs {
                screens::preferences(self, ui);
                return;
            }
            let idx = self.active.min(self.tabs.len().saturating_sub(1));
            let tab_id = self.tabs.get(idx).map(|t| t.id).unwrap_or(0);
            let recent: Vec<(String, String)> = self.settings.recent_repos.iter().map(|r| (r.name.clone(), r.path.clone())).collect();
            let ai_on = self.ai_on();
            let mut acts = Vec::new();
            let mut home_act = None;
            match self.tabs.get_mut(idx).map(|t| &mut t.kind) {
                Some(TabKind::Repo(r)) => {
                    let settings = self.settings.clone();
                    r.show(ui, &settings, &recent, &mut acts, ai_on);
                }
                Some(TabKind::Home) => home_act = home::home(ui, &recent),
                Some(TabKind::Launchpad) => home_act = home::launchpad(ui, &recent),
                Some(TabKind::ReleaseNotes) => home::release_notes(ui),
                Some(TabKind::Guide) => home::guide(ui),
                None => {}
            }
            for a in acts {
                actions::handle(self, tab_id, a);
            }
            if let Some(a) = home_act {
                home::handle(self, a);
            }
        });
    }
}

pub fn first_line(s: &str) -> String {
    s.lines().find(|l| !l.trim().is_empty()).unwrap_or("").chars().take(160).collect()
}

impl eframe::App for App {
    fn raw_input_hook(&mut self, _ctx: &egui::Context, raw: &mut egui::RawInput) {
        if let Some(st) = &mut self.selftest {
            for k in st.pending_keys.drain(..) {
                raw.events.push(egui::Event::Key { key: k, physical_key: None, pressed: true, repeat: false, modifiers: Default::default() });
                raw.events.push(egui::Event::Key { key: k, physical_key: None, pressed: false, repeat: false, modifiers: Default::default() });
            }
        }
    }

    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.frame += 1;
        self.status_drawn = false;
        let now = ctx.input(|i| i.time);
        self.process_jobs();
        actions::process_ai(self);
        self.poll_languages(now);
        if self.screen == Screen::Main {
            self.auto_refresh(now);
        }
        self.shortcuts(ctx);

        match self.screen {
            Screen::Onboarding(step) => screens::onboarding(self, ctx, step),
            Screen::Clone => screens::clone_page(self, ctx),
            Screen::Main | Screen::Prefs => {
                self.menu_bar(ctx);
                self.tab_bar(ctx);
                self.status_bar(ctx);
                self.central(ctx);
            }
        }
        screens::modals(self, ctx);
        self.toasts_ui(ctx);

        // --screenshot: draw ~120 frames, then save the picture and quit.
        if let Some(path) = self.screenshot.clone() {
            ctx.request_repaint();
            if self.frame >= 120 && !self.shot_requested {
                self.shot_requested = true;
                ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot);
            }
            let shot = ctx.input(|i| {
                i.raw.events.iter().find_map(|e| match e {
                    egui::Event::Screenshot { image, .. } => Some(image.clone()),
                    _ => None,
                })
            });
            if let Some(img) = shot {
                save_png(&path, &img);
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            }
            if self.frame > 600 {
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
            }
        }
        if self.selftest.is_some() {
            ctx.request_repaint();
            selftest::step(self, ctx);
        }
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        self.save_settings();
    }
}

fn save_png(path: &std::path::Path, img: &egui::ColorImage) {
    if let Some(d) = path.parent() {
        let _ = std::fs::create_dir_all(d);
    }
    let [w, h] = img.size;
    let mut buf = Vec::with_capacity(w * h * 4);
    for c in &img.pixels {
        buf.extend_from_slice(&[c.r(), c.g(), c.b(), 255]);
    }
    if let Some(im) = image::RgbaImage::from_raw(w as u32, h as u32, buf) {
        let _ = im.save(path);
    }
}

input.content:
//! The desktop app: window chrome (menu bar, tab bar, status bar), tabs,
//! background jobs, the screenshot and self-test modes.

pub mod actions;
pub mod home;
pub mod repo;
pub mod repo_graph;
pub mod repo_left;
pub mod repo_panels;
pub mod screens;
pub mod selftest;
pub mod theme;

use eframe::egui::{self, Align2, CursorIcon, Pos2, Rect, Rounding, Sense, Stroke, Vec2};
use egui_phosphor::regular as ic;
use gcc_core::ai::AiWorker;
use gcc_core::config::{AiMode, Settings};
use gcc_core::git::{self, Engine};
use gcc_core::gitdl::GitRelease;
use gcc_core::i18n::{self, t, tf};
use repo::RepoTab;
use std::path::PathBuf;
use std::sync::mpsc::{channel, Receiver, Sender};
use std::sync::{Arc, Mutex};
use theme::*;

pub enum TabKind {
    Launchpad,
    ReleaseNotes,
    Home,
    Guide,
    Repo(Box<RepoTab>),
}

pub struct Tab {
    pub id: u64,
    pub kind: TabKind,
}

impl Tab {
    pub fn title(&self) -> String {
        match &self.kind {
            TabKind::Launchpad => t("tabs.launchpad"),
            TabKind::ReleaseNotes => t("tabs.release_notes"),
            TabKind::Home => t("tabs.new_tab"),
            TabKind::Guide => t("tabs.guide"),
            TabKind::Repo(r) => r.name(),
        }
    }
    pub fn icon(&self) -> &'static str {
        match &self.kind {
            TabKind::Launchpad => ic::ROCKET_LAUNCH,
            TabKind::ReleaseNotes => ic::CLIPBOARD_TEXT,
            TabKind::Home => "",
            TabKind::Guide => ic::BOOK_OPEN,
            TabKind::Repo(_) => ic::GIT_BRANCH,
        }
    }
    pub fn key(&self) -> String {
        match &self.kind {
            TabKind::Launchpad => "#launchpad".into(),
            TabKind::ReleaseNotes => "#release".into(),
            TabKind::Home => "#home".into(),
            TabKind::Guide => "#guide".into(),
            TabKind::Repo(r) => r.path.display().to_string(),
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Screen {
    Main,
    Onboarding(u8),
    Clone,
    Prefs,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PrefPage {
    General,
    Profiles,
    Language,
    Ai,
    Git,
    Integrations,
    Mcp,
    Shortcuts,
}

#[derive(Clone, Debug)]
pub enum InputKind {
    NewBranch { tab: u64, at: Option<git2::Oid> },
    RenameBranch { tab: u64, old: String },
    Tag { tab: u64, oid: git2::Oid },
    Stash { tab: u64 },
    AddRemote { tab: u64 },
}

#[derive(Clone, Debug)]
pub enum ConfirmAction {
    DiscardAll(u64),
    Discard(u64, Vec<String>),
    ResetHard(u64, git2::Oid),
    DeleteBranch(u64, String),
    ForcePush(u64),
    DropStash(u64, usize),
    RemoveRemote(u64, String),
}

pub struct InitForm {
    pub provider: usize,
    pub name: String,
    pub parent: String,
    pub branch: String,
    pub gitignore: String,
    pub license: String,
    pub lfs: bool,
    pub remote: String,
}

pub enum Modal {
    Init(InitForm),
    Input { title: String, label: String, value: String, label2: String, value2: String, kind: InputKind },
    Confirm { title: String, text: String, action: ConfirmAction },
    About,
    Shortcuts,
}

pub struct Toast {
    pub text: String,
    pub error: bool,
    pub until: f64,
}

pub struct Job {
    pub id: u64,
    pub title: String,
    pub progress: Arc<Mutex<f32>>,
}

pub enum JobOut {
    Msg(String),
    Cloned(PathBuf),
    Releases(Vec<GitRelease>),
    GitInstalled(String),
    Models(Vec<String>),
    RepoList(Vec<(String, String)>),
}

pub struct JobDone {
    pub id: u64,
    pub tab: Option<u64>,
    pub title: String,
    pub result: Result<JobOut, String>,
}

#[derive(Default)]
pub struct CloneForm {
    pub provider: usize,
    pub url: String,
    pub parent: String,
    pub shallow: bool,
    pub sparse: bool,
    pub owner: String,
    pub repos: Vec<(String, String)>,
    pub loading: bool,
}

#[derive(Default)]
pub struct GitDlState {
    pub releases: Vec<GitRelease>,
    pub loading: bool,
    pub selected: usize,
    pub asset: usize,
    pub error: Option<String>,
    pub show_pre: bool,
    pub busy: bool,
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum AiPurpose {
    Chat,
    CommitMessage,
}

pub struct App {
    pub ctx: egui::Context,
    pub settings: Settings,
    pub tabs: Vec<Tab>,
    pub active: usize,
    pub next_id: u64,
    pub closed: Vec<String>,
    pub screen: Screen,
    pub pref_page: PrefPage,
    pub modal: Option<Modal>,
    pub toasts: Vec<Toast>,
    pub notifications: Vec<(String, bool)>,
    pub unread: usize,
    pub jobs: Vec<Job>,
    pub job_tx: Sender<JobDone>,
    pub job_rx: Receiver<JobDone>,
    pub job_seq: u64,
    pub engine: Engine,
    pub git_version: Option<String>,
    pub ai: AiWorker,
    pub ai_tab: Option<u64>,
    pub ai_purpose: AiPurpose,
    pub lang_poll: f64,
    pub clone_form: CloneForm,
    pub gitdl: GitDlState,
    pub onboard_name: String,
    pub onboard_email: String,
    pub screenshot: Option<PathBuf>,
    pub shot_requested: bool,
    pub selftest: Option<selftest::SelfTest>,
    pub frame: u64,
    pub status_drawn: bool,
    pub ai_models: Vec<String>,
    pub persist: bool,
    pub profile_open: bool,
    pub bell_open: bool,
    pub tabs_open: bool,
}

pub struct Options {
    pub screenshot: Option<PathBuf>,
    pub selftest: Option<PathBuf>,
    pub open: Option<PathBuf>,
}

pub fn make_engine(s: &Settings) -> Engine {
    let mut e = Engine::detect(&s.git_path_override, s.prefer_git_cli);
    let p = s.profile();
    e.user_name = p.user_name.clone();
    e.user_email = p.user_email.clone();
    e.token_github = s.github_token.clone();
    e.token_gitlab = s.gitlab_token.clone();
    e
}

impl App {
    pub fn new(cc: &eframe::CreationContext, opts: Options) -> Self {
        theme::setup(&cc.egui_ctx);
        let automated = opts.screenshot.is_some() || opts.selftest.is_some();
        let mut settings = if automated { Settings::default() } else { Settings::load() };
        if automated {
            settings.onboarding_done = true;
            settings.language = "en".into();
        }
        i18n::init(&settings.language);
        if let Ok(mut g) = i18n::global().write() {
            g.set_language(&settings.language);
        }
        // Fill the commit signature from Git's own settings the first time.
        if settings.profile().user_name.is_empty() {
            if let Some(n) = git::read_config(None, "user.name") {
                settings.profile_mut().user_name = n;
            }
            if let Some(m) = git::read_config(None, "user.email") {
                settings.profile_mut().user_email = m;
            }
        }
        let engine = make_engine(&settings);
        let git_version = engine.cli.as_ref().and_then(|p| git::git_version(p));
        let (job_tx, job_rx) = channel();
        let mut app = Self {
            ctx: cc.egui_ctx.clone(),
            onboard_name: settings.profile().user_name.clone(),
            onboard_email: settings.profile().user_email.clone(),
            screen: if settings.onboarding_done { Screen::Main } else { Screen::Onboarding(0) },
            settings,
            tabs: vec![],
            active: 0,
            next_id: 1,
            closed: vec![],
            pref_page: PrefPage::General,
            modal: None,
            toasts: vec![],
            notifications: vec![],
            unread: 0,
            jobs: vec![],
            job_tx,
            job_rx,
            job_seq: 0,
            engine,
            git_version,
            ai: AiWorker::start(),
            ai_tab: None,
            ai_purpose: AiPurpose::Chat,
            lang_poll: 0.0,
            clone_form: CloneForm::default(),
            gitdl: GitDlState::default(),
            screenshot: opts.screenshot,
            shot_requested: false,
            selftest: opts.selftest.map(selftest::SelfTest::new),
            frame: 0,
            status_drawn: false,
            ai_models: vec![],
            persist: !automated,
            profile_open: false,
            bell_open: false,
            tabs_open: false,
        };
        app.clone_form.parent = app.settings.default_clone_dir.clone();
        app.ctx.set_zoom_factor(app.settings.zoom);
        // Tabs like the reference: Launchpad, recent repositories, Release Notes, New Tab.
        app.add_tab(TabKind::Launchpad, false);
        let restore: Vec<String> = if automated { vec![] } else { app.settings.open_tabs.clone() };
        for p in restore {
            let pb = PathBuf::from(&p);
            if git::is_repo(&pb) {
                app.open_repo_tab(pb, false);
            }
        }
        app.add_tab(TabKind::ReleaseNotes, false);
        app.add_tab(TabKind::Home, true);
        if let Some(p) = opts.open {
            app.open_repo(p);
        }
        if app.engine.cli.is_none() && app.persist {
            app.notify(t("notify.git_missing"), false);
        }
        app
    }

    pub fn add_tab(&mut self, kind: TabKind, focus: bool) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        self.tabs.push(Tab { id, kind });
        if focus {
            self.active = self.tabs.len() - 1;
        }
        id
    }

    pub fn open_repo_tab(&mut self, path: PathBuf, focus: bool) -> u64 {
        if let Some(i) = self.tabs.iter().position(|t| matches!(&t.kind, TabKind::Repo(r) if r.path == path)) {
            if focus {
                self.active = i;
            }
            return self.tabs[i].id;
        }
        let mut r = RepoTab::new(path);
        r.reload(self.settings.graph_max_commits);
        // Insert before "Release Notes"/"New Tab" so repos stay grouped, like the reference.
        let pos = self
            .tabs
            .iter()
            .position(|t| matches!(t.kind, TabKind::ReleaseNotes | TabKind::Home))
            .unwrap_or(self.tabs.len());
        let id = self.next_id;
        self.next_id += 1;
        self.tabs.insert(pos, Tab { id, kind: TabKind::Repo(Box::new(r)) });
        if focus {
            self.active = pos;
        } else if self.active >= pos && self.tabs.len() > 1 {
            self.active += 1;
        }
        id
    }

    /// Open a repository (from a path) as the user would with "Open".
    pub fn open_repo(&mut self, path: PathBuf) {
        let repo_root = git2::Repository::discover(&path)
            .ok()
            .and_then(|r| r.workdir().map(|w| w.to_path_buf()))
            .unwrap_or(path.clone());
        if !git::is_repo(&repo_root) {
            self.toast(tf("notify.not_a_repo", &[&path.display().to_string()]), true);
            return;
        }
        let clean = PathBuf::from(repo_root.display().to_string().trim_end_matches(['/', '\\']));
        // Replace the current "New Tab" if that's where we are.
        let replace_home = matches!(self.tabs.get(self.active).map(|t| &t.kind), Some(TabKind::Home));
        let home_idx = self.active;
        self.open_repo_tab(clean.clone(), true);
        if replace_home && self.tabs.iter().filter(|t| matches!(t.kind, TabKind::Home)).count() > 0 {
            if let Some(i) = self.tabs.iter().position(|t| matches!(t.kind, TabKind::Home)) {
                if i == home_idx || i == home_idx + 1 {
                    self.tabs.remove(i);
                    if self.active > i {
                        self.active -= 1;
                    }
                }
            }
        }
        self.settings.add_recent(&clean.display().to_string());
        self.save_settings();
    }

    pub fn save_settings(&mut self) {
        if !self.persist {
            return;
        }
        self.settings.open_tabs = self
            .tabs
            .iter()
            .filter_map(|t| match &t.kind {
                TabKind::Repo(r) => Some(r.path.display().to_string()),
                _ => None,
            })
            .collect();
        let _ = self.settings.save();
    }

    pub fn toast(&mut self, text: impl Into<String>, error: bool) {
        let now = self.ctx.input(|i| i.time);
        let text = text.into();
        self.notifications.insert(0, (text.clone(), error));
        self.notifications.truncate(50);
        self.toasts.push(Toast { text, error, until: now + if error { 8.0 } else { 4.0 } });
    }

    pub fn notify(&mut self, text: impl Into<String>, error: bool) {
        self.notifications.insert(0, (text.into(), error));
        self.unread += 1;
    }

    pub fn ai_on(&self) -> bool {
        self.settings.ai.mode != AiMode::Off
    }

    pub fn spawn_job<F>(&mut self, title: String, tab: Option<u64>, f: F) -> u64
    where
        F: FnOnce(&mut dyn FnMut(f32, &str)) -> Result<JobOut, String> + Send + 'static,
    {
        self.job_seq += 1;
        let id = self.job_seq;
        let progress = Arc::new(Mutex::new(0.0f32));
        self.jobs.push(Job { id, title: title.clone(), progress: progress.clone() });
        let tx = self.job_tx.clone();
        let ctx = self.ctx.clone();
        std::thread::spawn(move || {
            let pc = progress.clone();
            let ctx2 = ctx.clone();
            let mut cb = move |f: f32, _l: &str| {
                if let Ok(mut p) = pc.lock() {
                    *p = f.clamp(0.0, 1.0);
                }
                ctx2.request_repaint();
            };
            let result = f(&mut cb);
            let _ = tx.send(JobDone { id, tab, title, result });
            ctx.request_repaint();
        });
        id
    }

    pub fn tab_mut(&mut self, id: u64) -> Option<&mut RepoTab> {
        self.tabs.iter_mut().find(|t| t.id == id).and_then(|t| match &mut t.kind {
            TabKind::Repo(r) => Some(r.as_mut()),
            _ => None,
        })
    }

    pub fn active_repo_id(&self) -> Option<u64> {
        self.tabs.get(self.active).and_then(|t| match t.kind {
            TabKind::Repo(_) => Some(t.id),
            _ => None,
        })
    }

    pub fn close_tab(&mut self, idx: usize) {
        if idx >= self.tabs.len() {
            return;
        }
        let tab = self.tabs.remove(idx);
        self.closed.push(tab.key());
        if self.tabs.is_empty() {
            self.add_tab(TabKind::Home, true);
        }
        if self.active >= self.tabs.len() {
            self.active = self.tabs.len() - 1;
        } else if self.active > idx {
            self.active -= 1;
        }
        self.save_settings();
    }

    pub fn reopen_closed(&mut self) {
        if let Some(k) = self.closed.pop() {
            match k.as_str() {
                "#launchpad" => {
                    self.add_tab(TabKind::Launchpad, true);
                }
                "#release" => {
                    self.add_tab(TabKind::ReleaseNotes, true);
                }
                "#home" => {
                    self.add_tab(TabKind::Home, true);
                }
                "#guide" => {
                    self.add_tab(TabKind::Guide, true);
                }
                p => {
                    self.open_repo_tab(PathBuf::from(p), true);
                }
            }
        }
    }

    pub fn new_tab(&mut self) {
        self.add_tab(TabKind::Home, true);
    }

    pub fn browse_open_repo(&mut self) {
        if self.selftest.is_some() || self.screenshot.is_some() {
            return;
        }
        if let Some(p) = rfd::FileDialog::new().set_title(t("menu.open_repo")).pick_folder() {
            self.open_repo(p);
        }
    }

    pub fn open_prefs(&mut self, page: PrefPage) {
        self.pref_page = page;
        self.screen = Screen::Prefs;
    }

    fn process_jobs(&mut self) {
        while let Ok(done) = self.job_rx.try_recv() {
            self.jobs.retain(|j| j.id != done.id);
            match done.result {
                Ok(JobOut::Msg(m)) => {
                    let text = if m.trim().is_empty() { tf("notify.done", &[&done.title]) } else { format!("{}: {}", done.title, first_line(&m)) };
                    self.toast(text, false);
                }
                Ok(JobOut::Cloned(p)) => {
                    self.toast(tf("notify.cloned", &[&p.display().to_string()]), false);
                    self.open_repo(p);
                    self.screen = Screen::Main;
                }
                Ok(JobOut::Releases(r)) => {
                    self.gitdl.releases = r;
                    self.gitdl.loading = false;
                    self.gitdl.selected = 0;
                    self.gitdl.asset = 0;
                    self.gitdl.error = None;
                }
                Ok(JobOut::GitInstalled(m)) => {
                    self.gitdl.busy = false;
                    self.engine = make_engine(&self.settings);
                    self.git_version = self.engine.cli.as_ref().and_then(|p| git::git_version(p));
                    let key = match m.as_str() {
                        "installer_started" => "gitdl.installer_started",
                        "source_saved" => "gitdl.source_saved",
                        _ => "gitdl.installed",
                    };
                    self.toast(t(key), false);
                }
                Ok(JobOut::Models(m)) => {
                    self.ai_models = m;
                }
                Ok(JobOut::RepoList(r)) => {
                    self.clone_form.repos = r;
                    self.clone_form.loading = false;
                }
                Err(e) => {
                    self.gitdl.loading = false;
                    self.gitdl.busy = false;
                    self.clone_form.loading = false;
                    if done.title == t("gitdl.title") {
                        self.gitdl.error = Some(e.clone());
                    }
                    self.toast(format!("{}: {}", done.title, e), true);
                }
            }
            if let Some(id) = done.tab {
                let max = self.settings.graph_max_commits;
                if let Some(r) = self.tab_mut(id) {
                    r.reload(max);
                }
            }
        }
    }

    fn poll_languages(&mut self, now: f64) {
        if now - self.lang_poll < 2.0 {
            return;
        }
        self.lang_poll = now;
        let mut new_names = Vec::new();
        if let Ok(mut g) = i18n::global().write() {
            if g.poll(&self.settings.language) {
                new_names = std::mem::take(&mut g.last_new);
            }
        }
        for n in new_names {
            self.toast(tf("notify.new_language", &[&n]), false);
        }
    }

    fn auto_refresh(&mut self, now: f64) {
        let max = self.settings.graph_max_commits;
        let fetch_every = self.settings.auto_fetch_minutes as f64 * 60.0;
        let mut fetch_tab: Option<(u64, PathBuf)> = None;
        if let Some(idx) = self.tabs.get(self.active).map(|_| self.active) {
            let id = self.tabs[idx].id;
            if let TabKind::Repo(r) = &mut self.tabs[idx].kind {
                if now - r.last_poll > 2.5 {
                    r.last_poll = now;
                    let fp = repo::fingerprint(&r.path);
                    if fp != r.fingerprint {
                        r.reload(max);
                    }
                }
                if fetch_every > 0.0 && now - r.last_fetch > fetch_every {
                    r.last_fetch = now;
                    fetch_tab = Some((id, r.path.clone()));
                }
            }
        }
        if let Some((id, path)) = fetch_tab {
            let e = self.engine.clone();
            self.spawn_job(t("jobs.auto_fetch"), Some(id), move |p| git::fetch(&e, &path, None, Some(p)).map(|_| JobOut::Msg(String::new())));
        }
    }

    fn shortcuts(&mut self, ctx: &egui::Context) {
        use egui::{Key, KeyboardShortcut, Modifiers};
        let cmd = Modifiers::COMMAND;
        let sc = |m: Modifiers, k: Key| ctx.input_mut(|i| i.consume_shortcut(&KeyboardShortcut::new(m, k)));
        if sc(cmd | Modifiers::SHIFT, Key::T) {
            self.reopen_closed();
        }
        if sc(cmd, Key::T) {
            self.new_tab();
        }
        if sc(cmd, Key::W) {
            self.close_tab(self.active);
        }
        if sc(cmd, Key::N) {
            self.screen = Screen::Clone;
        }
        if sc(cmd, Key::I) {
            self.modal = Some(screens::new_init_form(&self.settings));
        }
        if sc(cmd | Modifiers::ALT, Key::O) {
            self.add_tab(TabKind::Launchpad, true);
        }
        if sc(cmd, Key::O) {
            self.browse_open_repo();
        }
        if sc(cmd, Key::Comma) {
            self.open_prefs(PrefPage::General);
        }
        if sc(cmd, Key::Plus) || sc(cmd, Key::Equals) {
            self.set_zoom(self.settings.zoom + 0.1);
        }
        if sc(cmd, Key::Minus) {
            self.set_zoom(self.settings.zoom - 0.1);
        }
        if sc(cmd, Key::Num0) {
            self.set_zoom(1.0);
        }
        if sc(Modifiers::ALT, Key::T) {
            if let Some(id) = self.active_repo_id() {
                actions::handle(self, id, repo::RepoAction::OpenTerminal);
            }
        }
        if sc(cmd, Key::Tab) && !self.tabs.is_empty() {
            self.active = (self.active + 1) % self.tabs.len();
        }
        // Keyboard navigation in the graph.
        let typing = ctx.memory(|m| m.focused().is_some());
        if !typing && self.modal.is_none() && self.screen == Screen::Main {
            let down = ctx.input(|i| i.key_pressed(Key::ArrowDown));
            let up = ctx.input(|i| i.key_pressed(Key::ArrowUp));
            let esc = ctx.input(|i| i.key_pressed(Key::Escape));
            if let Some(TabKind::Repo(r)) = self.tabs.get_mut(self.active).map(|t| &mut t.kind) {
                if down {
                    r.move_selection(1);
                }
                if up {
                    r.move_selection(-1);
                }
                if esc {
                    r.diff = None;
                }
            }
        }
    }

    pub fn set_zoom(&mut self, z: f32) {
        self.settings.zoom = (z * 10.0).round() / 10.0;
        self.settings.zoom = self.settings.zoom.clamp(0.6, 2.0);
        self.ctx.set_zoom_factor(self.settings.zoom);
        self.save_settings();
    }

