                        act = Some(HomeAction::Clone);
                    }
                    if ui.button(format!("{} {}", ic::PLUS_SQUARE, t("home.create"))).clicked() {
                        act = Some(HomeAction::Create);
                    }
                });
            }
            for c in cards.iter() {
