                }
                p.text(Pos2::new(x, y + 16.0), Align2::LEFT_CENTER, t("onboard.card_more"), font(14.0), hex(0xB0B4BC));
                // Skip link
                let sy = full.top() + full.height() * 0.77;
                let pre = t("onboard.skip_q");
