//! GitCerberoCraft desktop app.
//!
//!   gitcerberocraft [repo-path]
//!   gitcerberocraft --screenshot shot.png   draw ~120 frames, save a PNG, quit
//!   gitcerberocraft --self-test result.json scripted check of the core loop

#![cfg_attr(all(windows, not(debug_assertions)), windows_subsystem = "windows")]

mod ui;

use eframe::egui;
use std::path::PathBuf;
use std::sync::Arc;

fn icon() -> egui::IconData {
    // Our own mark, drawn in code: a teal shield with three small heads.
    let n = 64usize;
    let mut rgba = vec![0u8; n * n * 4];
    let teal = [0x6F, 0xD3, 0xC3, 0xFF];
    let dark = [0x14, 0x18, 0x1E, 0xFF];
    for y in 0..n {
        for x in 0..n {
            let fx = (x as f32 - 32.0) / 30.0;
            let fy = (y as f32 - 32.0) / 30.0;
            let inside = fy > -0.75 && fx.abs() < 0.8 && (fy < 0.05 || fx.abs() < 0.8 * (1.0 - (fy - 0.05) / 0.95));
            let mut c = if inside { teal } else { [0, 0, 0, 0] };
            for hx in [-0.42f32, 0.0, 0.42] {
                let hy = if hx == 0.0 { -0.34 } else { -0.22 };
                if inside && ((fx - hx).powi(2) + (fy - hy).powi(2)).sqrt() < 0.2 {
                    c = dark;
                }
            }
            if inside && fy > 0.31 && fy < 0.39 && fx.abs() < 0.3 {
                c = dark;
            }
            rgba[(y * n + x) * 4..(y * n + x) * 4 + 4].copy_from_slice(&c);
        }
    }
    egui::IconData { rgba, width: n as u32, height: n as u32 }
}

fn main() -> eframe::Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut screenshot = None;
    let mut selftest = None;
    let mut open = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--screenshot" => {
                screenshot = args.get(i + 1).map(PathBuf::from);
                i += 1;
            }
            "--self-test" => {
                selftest = args.get(i + 1).map(PathBuf::from);
                i += 1;
            }
            a if !a.starts_with('-') => open = Some(PathBuf::from(a)),
            _ => {}
        }
        i += 1;
    }
    let automated = screenshot.is_some() || selftest.is_some();
    let mut viewport = egui::ViewportBuilder::default()
        .with_title("GitCerberoCraft")
        .with_inner_size([1232.0, 760.0])
        .with_min_inner_size([820.0, 520.0])
        .with_icon(Arc::new(icon()));
    if automated {
        viewport = viewport.with_active(false);
        #[cfg(windows)]
        {
            viewport = viewport.with_window_level(egui::WindowLevel::AlwaysOnBottom);
        }
    }
    let options = eframe::NativeOptions { viewport, run_and_return: true, ..Default::default() };
    eframe::run_native(
        "GitCerberoCraft",
        options,
        Box::new(move |cc| Ok(Box::new(ui::App::new(cc, ui::Options { screenshot, selftest, open })))),
    )
}

