878	pub fn commit(engine: &Engine, path: &Path, message: &str, amend: bool) -> GResult<Oid> {
879	    if message.trim().is_empty() {
880	        return Err("The commit message is empty".into());
881	    }
882	    let mut repo = open(path)?;
883	    let sig = signature(&repo, engine)?;
884	    let mut idx = repo.index().es()?;
885	    if idx.has_conflicts() {
886	        return Err("Resolve the conflicts before committing".into());
887	    }
888	    let tree_id = idx.write_tree().es()?;
889	    let tree = repo.find_tree(tree_id).es()?;
890	    let head = repo.head().ok().and_then(|h| h.peel_to_commit().ok());
891	    if amend {
892	        let h = head.ok_or("Nothing to amend")?;
893	        let oid = h.amend(Some("HEAD"), None, Some(&sig), None, Some(message), Some(&tree)).es()?;
894	        return Ok(oid);
895	    }
896	    if let Some(h) = &head {
897	        if h.tree_id() == tree_id && repo.state() != git2::RepositoryState::Merge {
898	            return Err("No staged changes to commit".into());
899	        }
900	    }
901	    let mut parents = Vec::new();
902	    if let Some(h) = head {
903	        parents.push(h);
